const lessons = [
  {"num": 2, "time": "00:00:30,000 --> 00:00:48,900", "arabic": "يَا اللَّهُ", "segs": null, "full_uz": "Yo Alloh.", "note": null},
  {"num": 3, "time": "00:00:48,900 --> 00:00:56,019", "arabic": "إِنَّكَ ابْتَلَيْتَ عَبْدَكَ هَارُونَ بِوِلَايَةِ أَمْرِ الْمُسْلِمِينَ", "segs": null, "full_uz": "Sen bandang Horunni musulmonlar ishini boshqarish bilan sinovga soldingiz.", "note": null},
  {"num": 4, "time": "00:00:56,019 --> 00:01:03,039", "arabic": "فَأَعِنِّي عَلَى الْقِيَامِ بِهَا عَلَى الْوَجْهِ الَّذِي يُرْضِيكَ عَنِّي", "segs": null, "full_uz": "Shuni Sizni mendan rozi qiladigan tarzda bajarishimga yordam ber.", "note": null},
  {"num": 7, "time": "00:01:03,039 --> 00:01:13,620", "arabic": "اَللَّهُمَّ إِنَّ الْحَمْلَ ثَقِيلٌ وَالْخَطْبَ جَلِيلٌ", "segs": null, "full_uz": "Yo Alloh, yuk og'ir, ish esa ulug'vordir.", "note": null},
  {"num": 10, "time": "00:01:13,620 --> 00:01:23,280", "arabic": "فَاشْدُدْ بِالْعُلَمَاءِ أَزْرِي وَقَوِّ بِالنَّاصِحِينَ الْمُخْلِصِينَ ظَهْرِي", "segs": null, "full_uz": "Olimlar bilan kuchimni mustahkamla, va sodiq nasihatchilar bilan yelkamni quvvatla.", "note": null},
  {"num": 13, "time": "00:01:23,280 --> 00:01:28,519", "arabic": "وَأَشْرِكْهُمْ فِي أَمْرِي", "segs": null, "full_uz": "Va ularni ishimga sherik qil.", "note": null},
  {"num": 15, "time": "00:01:28,519 --> 00:01:37,640", "arabic": "وَتَوَلَّ أَنْتَ جَمِيعَ أَمْرِي يَا أَرْحَمَ الرَّاحِمِينَ يَا اللَّهُ", "segs": null, "full_uz": "Va butun ishimni O'zing boshqar, ey rahmlilarning eng rahmlisi, yo Alloh.", "note": null},
  {"num": 22, "time": "00:01:58,919 --> 00:02:03,739", "arabic": "هَا؟", "segs": null, "full_uz": "Ha?", "note": null},
  {"num": 23, "time": "00:02:03,739 --> 00:02:06,179", "arabic": "أَلَنْ تُسَاعِدَنِي يَا صَدِيقِي؟", "segs": null, "full_uz": "Menga yordam bermaysanmi, do'stim?", "note": null},
  {"num": 24, "time": "00:02:06,179 --> 00:02:12,439", "arabic": "أَنْتَ تَعْرِفُ أَنَّنِي أُرِيدُ مُسَاعَدَتَكَ يَا بَدْرُ، وَلَكِنِّي أَخْشَى أَنَّ صَاحِبَكَ هَذَا سَيَجْلِبُ لِي الْمَتَاعِبَ", "segs": null, "full_uz": "Yordam berishni xohlashimni bilasan, Badr, lekin bu do'sting menga tashvish keltirishidan qo'rqaman.", "note": null},
  {"num": 26, "time": "00:02:12,439 --> 00:02:18,139", "arabic": "فَأَنْتَ مُنْذُ تَرَدُّدِكَ إِلَى الْمَرِيسِيِّ وَصَاحِبِهِ مِنَ الْمُعْتَزِلَةِ أَصْبَحْتَ تُخِيفُنِي", "segs": null, "full_uz": "Marisiy va uning mu'tazila do'stiga qatnashing beri meni qo'rqitadigan bo'lib qolding.", "note": null},
  {"num": 28, "time": "00:02:18,139 --> 00:02:23,180", "arabic": "لَا لَا، إِنَّهُ رَجُلٌ طَيِّبٌ وَلَا أَحْسَبُ أَنَّهُ سَيُسَبِّبُ لَكَ الْمَتَاعِبَ", "segs": null, "full_uz": "Yo'q, yo'q, u yaxshi odam, senga tashvish keltiradi deb o'ylamayman.", "note": null},
  {"num": 30, "time": "00:02:23,180 --> 00:02:34,379", "arabic": "لَا أَدْرِي مَاذَا أَقُولُ لَكَ يَا بَدْرُ، وَلَكِنِّي أَرَى أَنَّكَ سَتُصَدِّعُ رَأْسِي وَأَنَا أَكْرَهُ مَا يُصَدِّعُ رَأْسِي حَتَّى وَإِنْ كَانَ عَطْرًا", "segs": null, "full_uz": "Senga nima deyishni bilmayman, Badr, lekin boshimni og'ritishing ko'rinib turibdi, men esa hatto atir bo'lsa ham boshimni og'ritadigan narsani yoqtirmayman.", "note": null},
  {"num": 33, "time": "00:02:34,379 --> 00:02:42,060", "arabic": "لَا لَا إِنَّهُ رَجُلٌ طَيِّبٌ وَأَنَا أَعِدُكَ بِأَنَّنِي سَأُعَرِّفُكَ إِلَيْهِ قَبْلَ أَنْ يَسْتَأْجِرَ بَيْتَكَ لِكَيْ تَطْمَئِنَّ", "segs": null, "full_uz": "Yo'q, yo'q, u yaxshi odam, va senga va'da beraman, xotirjam bo'lishing uchun uyingni ijaraga olishidan oldin uni senga tanishtiraman.", "note": null},
  {"num": 35, "time": "00:02:42,060 --> 00:02:45,379", "arabic": "مَا اسْمُ الرَّجُلِ قُلْتَ لِي؟", "segs": null, "full_uz": "Odamning ismi nima edi, aytding?", "note": null},
  {"num": 36, "time": "00:02:45,379 --> 00:02:47,480", "arabic": "أَحْمَدُ بْنُ أَبِي دُؤَادٍ الْإِيَادِيُّ", "segs": null, "full_uz": "Ahmad ibn Abi Du'ad al-Iyodiy.", "note": null},
  {"num": 37, "time": "00:02:47,480 --> 00:02:50,379", "arabic": "إِيَادِيٌّ؟", "segs": null, "full_uz": "Iyodiymi?", "note": null},
  {"num": 39, "time": "00:02:50,379 --> 00:03:00,000", "arabic": "اِسْتَوْدَعَ اللَّهُ دِينَكَ وَأَمَانَتَكَ وَخَوَاتِيمَ عَمَلِكَ، اِسْتَوْدَعَكَ اللَّهَ الَّذِي لَا تَضِيعُ وَدَائِعُهُ", "segs": null, "full_uz": "Dining, omonating va amallaring xotimasini Allohga topshirdim. Seni vaqf-omonatlari zoye bo'lmaydigan Allohga topshiraman.", "note": "«اِسْتَوْدَعَ اللَّهَ» — «Allohga topshirdim», safarga chiqayotgan yoki uzoq vaqt ayriladigan kishiga aytiladigan an'anaviy islomiy xayrlashuv duosi."},
  {"num": 46, "time": "00:03:31,000 --> 00:03:41,239", "arabic": "مَا الَّذِي يَدُورُ دَاخِلَ هَذَا الْمَنْزِلِ؟", "segs": null, "full_uz": "Bu uy ichida nima bo'layapti?", "note": null},
  {"num": 48, "time": "00:03:43,239 --> 00:03:48,899", "arabic": "يَبْدُو أَنَّ هُنَاكَ أَمْرًا مُرِيبًا", "segs": null, "full_uz": "Shubhali bir ish borga o'xshaydi.", "note": null},
  {"num": 49, "time": "00:03:48,899 --> 00:03:53,340", "arabic": "اَلْأَخْبَارُ لَا تَسْعَى بَلْ يُسْعَى إِلَيْهَا يَا فَرَجُ", "segs": null, "full_uz": "Xabarlar o'zi kelmaydi, ularning orqasidan yuriladi, Faraj.", "note": null},
  {"num": 51, "time": "00:03:53,340 --> 00:03:58,200", "arabic": "هَلْ أَنْتَ مُتَأَكِّدٌ مِنْ هَذَا الْخَبَرِ يَا ابْنَ الْأَشْرَسِ؟", "segs": null, "full_uz": "Bu xabardan ishonchingiz komilmi, Ibn al-Ashras?", "note": null},
  {"num": 52, "time": "00:03:58,200 --> 00:04:03,940", "arabic": "أَجَلْ يَا أَبَا عَبْدِ الرَّحْمَنِ، اَلْيَوْمَ عَصْرًا اقْتَادَ رِجَالُ الطَّاغِيَةِ أَخًا لَنَا إِلَى الْحَبْسِ", "segs": null, "full_uz": "Ha, Abu Abdurahmon, bugun asrda zolim odamlari birodarimizni qamoqqa olib ketishdi.", "note": null},
  {"num": 54, "time": "00:04:03,940 --> 00:04:05,300", "arabic": "كَيْفَ؟", "segs": null, "full_uz": "Qanday qilib?", "note": null},
  {"num": 55, "time": "00:04:05,300 --> 00:04:16,920", "arabic": "اَلرَّجُلُ الَّذِي اقْتَادُوهُ مِنْ إِخْوَتِنَا الَّذِينَ لَا تَأْخُذُهُمْ فِي اللَّهِ لَوْمَةُ لَائِمٍ، وَلَا يَخْشَى مِنَ الْمُجَاهَرَةِ بِرَأْيِهِ فِي مَكَانٍ", "segs": null, "full_uz": "Olib ketilgan odam — Alloh yo'lida hech kimning malomatidan qo'rqmaydigan va biror joyda o'z fikrini oshkora aytishdan cho'chimaydigan birodarlarimizdan biri.", "note": "«لَا تَأْخُذُهُمْ فِي اللَّهِ لَوْمَةُ لَائِمٍ» — Qur'oni karimning Ma'ida surasi, 54-oyatidan olingan mashhur ibora, Alloh yo'lida hech kimning tanbehidan qo'rqmaslikni bildiradi."},
  {"num": 58, "time": "00:04:16,920 --> 00:04:21,239", "arabic": "يَبْدُو أَنَّ أَحَدَهُمْ وَشَى بِهِ", "segs": null, "full_uz": "Kimdir uni sotgan ko'rinadi.", "note": null},
  {"num": 59, "time": "00:04:21,239 --> 00:04:27,180", "arabic": "حِينَ أَقُولُ لَكُمْ خُذُوا حَذَرَكُمْ تَسْخَرُونَ مِنِّي", "segs": null, "full_uz": "Senlarga ehtiyot bo'linglar deganimda, meni mazax qilasizlar.", "note": null},
  {"num": 61, "time": "00:04:27,180 --> 00:04:32,679", "arabic": "إِنَّهَا حَرْبٌ، حَرْبٌ عَلَى الْإِسْلَامِ يَخُوضُهَا هَارُونُ وَزَبَانِيَتُهُ", "segs": null, "full_uz": "Bu — urush, Islomga qarshi urush, uni Horun va uning jallodlari olib boryapti.", "note": null},
  {"num": 64, "time": "00:04:39,679 --> 00:04:41,819", "arabic": "اَللَّهُ الْمُسْتَعَانُ", "segs": null, "full_uz": "Yordamni faqat Allohdan so'raymiz.", "note": null},
  {"num": 65, "time": "00:04:41,819 --> 00:04:46,119", "arabic": "وَمَا الَّذِي حَمَلَكَ عَلَى الْقَوْلِ إِنَّ الْقُرْآنَ مَخْلُوقٌ", "segs": null, "full_uz": "Seni Qur'on yaratilgan deb aytishga nima majbur qildi?", "note": null},
  {"num": 68, "time": "00:04:46,119 --> 00:04:53,919", "arabic": "بَلْ شَيْطَانُكَ أَيُّهَا الْمَارِقُ الْكَافِرُ، أَبَلَغَتْ بِكُمُ الْوَقَاحَةُ أَنْ تَتَقَوَّلُوا فِي دِينِ اللَّهِ", "segs": null, "full_uz": "Balki seni shaytoning majbur qilgandir, ey mo'tadil kofir. Betamizligingiz shu darajaga yetdimi, Alloh dinida gap to'qiysiz?", "note": null},
  {"num": 70, "time": "00:04:53,919 --> 00:04:58,819", "arabic": "اِعْلَمُوا أَنَّ هَذَا لَنْ يَكُونَ فِي مُلْكِي وَأَنَا عَلَى قَيْدِ الْحَيَاةِ", "segs": null, "full_uz": "Bilib qo'yinglar, men tirik ekanman, bunday narsa mening mulkimda bo'lmaydi.", "note": null},
  {"num": 71, "time": "00:04:58,819 --> 00:05:04,880", "arabic": "اِسْمَعْ أَيُّهَا الْأَثِيمُ", "segs": null, "full_uz": "Eshit, ey gunohkor.", "note": null},
  {"num": 72, "time": "00:05:04,880 --> 00:05:09,540", "arabic": "إِنِّي أَمْنَحُكَ فُرْصَةً أَخِيرَةً لِتَتَرَاجَعَ عَنْ تَجْدِيفِكَ بِحَقِّ دِينِ اللَّهِ", "segs": null, "full_uz": "Senga Alloh diniga qarshi kufring haqida qaytishga oxirgi imkoniyat beraman.", "note": null},
  {"num": 73, "time": "00:05:09,540 --> 00:05:14,199", "arabic": "وَإِلَّا فَأُقْسِمُ بِرَبِّ هَارُونَ أَنْ أَجْعَلَكَ عِبْرَةً لِمَنْ يَعْتَبِرُ", "segs": null, "full_uz": "Aks holda, Horunning Robbisiga qasamki, seni ibrat oladiganlar uchun ibrat qilib qo'yaman.", "note": null},
  {"num": 74, "time": "00:05:14,199 --> 00:05:16,399", "arabic": "لَنْ أَتَرَاجَعَ", "segs": null, "full_uz": "Qaytmayman.", "note": null},
  {"num": 75, "time": "00:05:16,399 --> 00:05:18,199", "arabic": "هُوَ ذَا يَا قَاضِيَ الْقُضَاةِ", "segs": null, "full_uz": "Mana u, qozilar qozisi.", "note": null},
  {"num": 76, "time": "00:05:18,199 --> 00:05:24,239", "arabic": "خُذُوهُ وَحَاكِمُوهُ وَأَنْزِلُوا بِهِ الْعِقَابَ الَّذِي يَسْتَحِقُّ", "segs": null, "full_uz": "Uni oling, sud qilinglar va munosib jazoni bering.", "note": null},
  {"num": 77, "time": "00:05:24,239 --> 00:05:32,079", "arabic": "وَلْيَعْلَمِ الْجَمِيعُ أَنَّ هَارُونَ الرَّشِيدَ لَنْ يَسْمَحَ لِأَحَدٍ أَنْ يَتَقَوَّلَ فِي دِينِ اللَّهِ أَبَدًا", "segs": null, "full_uz": "Va hamma bilib qo'ysinki, Horun ar-Rashid hech kimga Alloh dinida gap to'qishga hech qachon ruxsat bermaydi.", "note": null},
  {"num": 79, "time": "00:05:32,079 --> 00:05:33,199", "arabic": "خُذُوهُ", "segs": null, "full_uz": "Uni olinglar.", "note": null},
  {"num": 80, "time": "00:05:39,199 --> 00:05:44,540", "arabic": "صِرْنَا نُشْبِهُ أَهْلَ الْعِلْمِ حَقًّا يَا أَحْمَدُ، هَا نَحْنُ نَرْحَلُ لِطَلَبِ الْحَدِيثِ الشَّرِيفِ", "segs": null, "full_uz": "Endi rostdan ham ilm ahliga o'xshab qoldik, Ahmad — mana, sharif hadis izlab yo'lga chiqyapmiz.", "note": null},
  {"num": 82, "time": "00:05:44,540 --> 00:05:50,819", "arabic": "غَدًا سَتَمَلُّ مِنَ التَّرْحَالِ يَا مُحَمَّدُ حِينَ تُشْرِقُ الْمَطَايَا بِكَ وَتَغْرُبُ", "segs": null, "full_uz": "Ertaga safar-jarayondan zerikasan, Muhammad, ulov ustida quyosh chiqishi-yu botishini kuzatib.", "note": null},
  {"num": 84, "time": "00:05:50,819 --> 00:05:55,940", "arabic": "أَلَا أَرَاكَ مُنْقَبِضَ النَّفْسِ يَا أَحْمَدُ؟ وَقَدْ كُنْتَ تَذُوبُ شَوْقًا لِهَذِهِ الرِّحْلَةِ", "segs": null, "full_uz": "Kayfiyating tushib qolganini ko'rmayapmanmi, Ahmad? Axir bu safarga zor bo'lib erib ketardingku.", "note": null},
  {"num": 86, "time": "00:05:55,940 --> 00:06:03,220", "arabic": "يَعْلَمُ اللَّهُ أَنَّنِي كَذَلِكَ بَلْ أَبْعَدُ مِنْ ذَلِكَ، وَلَكِنْ سَعَادَتِي لَمْ تَكْتَمِلْ وَسُرُورِي تُكَدِّرُهُ الْحَسْرَةُ", "segs": null, "full_uz": "Alloh biladiki, shundayman, hatto bundan ham ko'proq, lekin baxtim to'liq emas, quvonchimni hasrat xiralashtiryapti.", "note": null},
  {"num": 90, "time": "00:06:03,220 --> 00:06:08,120", "arabic": "حَزِينٌ عَلَى فِرَاقِ أُمِّكَ أَلَيْسَ كَذَلِكَ؟", "segs": null, "full_uz": "Onangdan ayrilganingga g'amgin bo'lyapsan, shunday emasmi?", "note": null},
  {"num": 91, "time": "00:06:08,120 --> 00:06:09,819", "arabic": "لَا أَدْرِي", "segs": null, "full_uz": "Bilmayman.", "note": null},
  {"num": 92, "time": "00:06:09,819 --> 00:06:16,819", "arabic": "أَشْعُرُ أَنِّي لَمْ أَرْأَفْ بِنَفْسِي حِينَ حَدَّثْتُهَا فِي أَمْرِ التَّرْحَالِ", "segs": null, "full_uz": "Unga safar haqida gapirganimda, o'zimga rahm qilmagandekman.", "note": null},
  {"num": 93, "time": "00:06:16,819 --> 00:06:22,120", "arabic": "كَيْفَ اسْتَطَعْتُ أَنْ أَتْرُكَهَا وَحِيدَةً دُونَ مُعِينٍ؟", "segs": null, "full_uz": "Uni yordamsiz, yolg'iz qanday tashlab ketolgan bo'lsam ekan?", "note": null},
  {"num": 94, "time": "00:06:22,120 --> 00:06:26,760", "arabic": "أَحْمَدُ، أَلَمْ تَقُلْ لِي أَنَّهَا هِيَ مَنْ أَثَارَتْ حَمَاسَكَ عَلَى هَذِهِ الرِّحْلَةِ؟", "segs": null, "full_uz": "Ahmad, senga bu safarga ishtiyoqingni qo'zg'atgan aynan u dema edingmi?", "note": null},
  {"num": 95, "time": "00:06:26,760 --> 00:06:32,220", "arabic": "أَجَلْ، وَلَكِنْ مَعَ ذَلِكَ أَشْعُرُ أَنَّنِي تَرَكْتُ حُزْنًا فِي قَلْبِهَا، حَاوَلَتْ أَنْ تُخْفِيَهُ عَنِّي", "segs": null, "full_uz": "Ha, lekin shunga qaramay, uning qalbida g'am qoldirganimni his qilyapman — u buni mendan yashirishga urindi.", "note": null},
  {"num": 97, "time": "00:06:32,220 --> 00:06:36,540", "arabic": "أَبْشِرْ بِعِزِّكَ يَا قَاسِمُ إِنْ كَانَ الْخَبَرُ صَحِيحًا", "segs": null, "full_uz": "Agar xabar to'g'ri bo'lsa, izzatingga suyun, Qosim.", "note": null},
  {"num": 98, "time": "00:06:36,540 --> 00:06:38,300", "arabic": "إِنَّهُ لَصَحِيحٌ يَا مَوْلَايَ", "segs": null, "full_uz": "Albatta to'g'ri, xo'jayinim.", "note": null},
  {"num": 99, "time": "00:06:38,300 --> 00:06:45,000", "arabic": "لَقَدْ سَمَحَ جَعْفَرٌ الْبَرْمَكِيُّ لِيَحْيَى بْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ أَنْ يَفِرَّ مِنْ سِجْنِهِ", "segs": null, "full_uz": "Ja'far al-Barmakiy Yahyo ibn Abdulloh at-Tolibiyga zindonidan qochishga ruxsat berdi.", "note": null},
  {"num": 100, "time": "00:06:45,000 --> 00:06:50,159", "arabic": "وَلَمْ آتِكَ إِلَى هُنَا حَتَّى تَأَكَّدْتُ أَنَّ يَحْيَى الطَّالِبِيَّ لَيْسَ فِي مَحْبِسِهِ", "segs": null, "full_uz": "Yahyo at-Tolibiy zindonida yo'qligiga aminmasdan sizga kelmadim.", "note": null},
  {"num": 101, "time": "00:06:50,159 --> 00:06:52,320", "arabic": "أَحْسَنْتَ يَا قَاسِمُ", "segs": null, "full_uz": "Barakalla, Qosim.", "note": null},
  {"num": 102, "time": "00:06:52,320 --> 00:06:58,780", "arabic": "هَذِهِ هِيَ الْأَخْبَارُ الَّتِي تَسْتَحِقُّ أَنْ أَمْلَأَ شِدْقَيْكَ عَلَيْهَا ذَهَبًا", "segs": null, "full_uz": "Mana shunday xabar uchun og'zingni oltinga to'ldirsa arziydi.", "note": null},
  {"num": 104, "time": "00:07:16,780 --> 00:07:20,700", "arabic": "لَقَدْ مَرَّ مِنَ السِّنِينَ مَا هُوَ كَفِيلٌ أَنْ يُنْسِيَكَ أَهْلَكَ", "segs": null, "full_uz": "Seni oilangni unuttiradigan qadar yillar o'tdi.", "note": null},
  {"num": 105, "time": "00:07:20,700 --> 00:07:26,700", "arabic": "لَوْ قَدَّرَ اللَّهُ لَكَ أَنْ تَلْتَقِيَ بِهِمْ لَالْتَقَيْتُمْ مُنْذُ زَمَنٍ بَعِيدٍ", "segs": null, "full_uz": "Agar Alloh ular bilan uchrashishni sizga taqdir qilganida, ancha oldin uchrashib bo'lardingiz.", "note": null},
  {"num": 107, "time": "00:07:26,700 --> 00:07:30,559", "arabic": "لَا اعْتِرَاضَ عَلَى إِرَادَةِ اللَّهِ وَقَدَرِهِ", "segs": null, "full_uz": "Allohning irodasi va taqdiriga qarshi hech qanday e'tiroz yo'q.", "note": null},
  {"num": 108, "time": "00:07:30,559 --> 00:07:34,559", "arabic": "لَكِنْ خَيَالُهُمْ حَاضِرٌ فِي ذِهْنِي لَا يَكَادُ يُفَارِقُنِي", "segs": null, "full_uz": "Lekin ularning tasavvuri xayolimda deyarli tark etmaydi.", "note": null},
  {"num": 109, "time": "00:07:34,559 --> 00:07:39,940", "arabic": "أَرَاهُمْ فِي كُلِّ نَاحِيَةٍ مِنَ الْبَيْتِ، أَشْعُرُ أَنَّهُمْ يَسْكُنُونَ مَعِي", "segs": null, "full_uz": "Ularni uyning har burchagida ko'raman, go'yo men bilan yashayotgandek his qilaman.", "note": null},
  {"num": 111, "time": "00:07:39,940 --> 00:07:45,940", "arabic": "أَرَاهُمْ يُخَاطِبُونَنِي وَأَنَا نَفْسِي أُخَاطِبُهُمْ، كَأَنَّنَا لَمْ نَفْتَرِقْ إِلَّا بِالْأَمْسِ", "segs": null, "full_uz": "Ularning menga gapirayotganini ko'raman, o'zim ham ularga gapiraman — go'yo faqat kecha ayrilgandekmiz.", "note": null},
  {"num": 114, "time": "00:07:45,940 --> 00:07:51,679", "arabic": "وَلَكِنْ بَعْدَ كُلِّ هَذِهِ السِّنِينَ لَقَدْ أَضْحَى اللِّقَاءُ صَعْبًا", "segs": null, "full_uz": "Lekin shuncha yillardan keyin uchrashuv qiyinlashdi.", "note": null},
  {"num": 117, "time": "00:07:51,679 --> 00:07:58,559", "arabic": "لَا يَا مَرْوَانُ، أَنَا لَنْ أَمَلَّ مِنْ أَمَلِ لِقَائِهِمْ وَلَنْ أَقْطَعَ رَجَائِي فِي أَنْ أَجِدَ أَهْلِي قَبْلَ أَنْ أَمُوتَ", "segs": null, "full_uz": "Yo'q, Marvon, men ular bilan uchrashish umididan hech charchamayman, va o'lishimdan oldin oilamni topish umidimni uzmayman.", "note": null},
  {"num": 120, "time": "00:07:58,559 --> 00:08:03,159", "arabic": "إِنَّنِي مُتَشَوِّقٌ لِسَمَاعِ يَزِيدَ ابْنِ هَارُونَ إِمَامِ أَهْلِ وَاسِطٍ", "segs": null, "full_uz": "Vosit ahlining imomi Yazid ibn Horunni tinglashga zorman.", "note": null},
  {"num": 121, "time": "00:08:03,159 --> 00:08:08,020", "arabic": "كَمْ مَرَّةٍ سَمِعْتُ مِنْكَ هَذَا الْكَلَامَ يَا أَحْمَدُ", "segs": null, "full_uz": "Bu gapni sendan necha marta eshitdim, Ahmad.", "note": null},
  {"num": 122, "time": "00:08:08,020 --> 00:08:12,220", "arabic": "وَكُلَّمَا رَأَيْتَ شَيْخًا عَالِمًا أَقْبَلْتَ عَلَيْهِ بِشَغَفٍ", "segs": null, "full_uz": "Har safar bilimdon shayxni ko'rganingda, unga ishtiyoq bilan yopishasan.", "note": null},
  {"num": 123, "time": "00:08:12,220 --> 00:08:16,940", "arabic": "تَعْلَمُ أَغْبِطُكَ عَلَى وَلُوعِكَ هَذَا، بَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Bilib qo'y, sening bu ishtiyoqingga havas qilaman, Alloh senga baraka bersin.", "note": null},
  {"num": 124, "time": "00:08:16,940 --> 00:08:20,240", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 125, "time": "00:08:20,240 --> 00:08:22,940", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 126, "time": "00:08:22,940 --> 00:08:29,540", "arabic": "إِنِّي أَرَى وُجُوهًا قَدْ أَيْنَعَتْ وَحَنَّكَتْهَا التَّجَارِبُ", "segs": null, "full_uz": "Pishib yetilgan va tajribalar sinovidan o'tgan yuzlarni ko'rib turibman.", "note": null},
  {"num": 127, "time": "00:08:29,540 --> 00:08:32,540", "arabic": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ", "segs": null, "full_uz": "Bismillahir Rohmanir Rohim.", "note": null},
  {"num": 128, "time": "00:08:32,540 --> 00:08:34,540", "arabic": "دَرْسُنَا الْيَوْمَ", "segs": null, "full_uz": "Bugungi darsimiz...", "note": null},
  {"num": 129, "time": "00:09:01,000 --> 00:09:04,940", "arabic": "مَرَارَةُ الْبَيْنِ تَكَادُ تَقْتُلُنِي يَا أُمَّ خَالِدٍ", "segs": null, "full_uz": "Ayriliq achchig'i meni deyarli o'ldirayozdi, Umm Xolid.", "note": null},
  {"num": 130, "time": "00:09:04,940 --> 00:09:09,059", "arabic": "فَكَيْفَ سَوَّغَتْ لِي نَفْسِي أَنْ أُفَارِقَ وَلَدِيَ الْوَحِيدَ", "segs": null, "full_uz": "Ichim yagona o'g'limdan ayrilishga qanday yo'l qo'ydi ekan.", "note": null},
  {"num": 131, "time": "00:09:09,059 --> 00:09:14,760", "arabic": "وَمَعَ ذَلِكَ فَإِنَّ مَا يُعَزِّينِي هُوَ أَنَّهُ ذَهَبَ لِطَلَبِ الْعِلْمِ", "segs": null, "full_uz": "Shunga qaramay, meni tasalli beradigan narsa — u ilm izlagani ketgani.", "note": null},
  {"num": 133, "time": "00:09:14,760 --> 00:09:20,540", "arabic": "اَلْأَمْرُ الَّذِي حَرَصْتُ عَلَيْهِ دَوْمًا، وَلَكِنِّي بِتُّ أَعُدُّ الْأَيَّامَ شَوْقًا لِرُؤْيَتِهِ", "segs": null, "full_uz": "Bu — men doim intilgan narsa, lekin endi uni ko'rish uchun kunlarni sanay boshladim.", "note": null},
  {"num": 134, "time": "00:09:20,540 --> 00:09:27,340", "arabic": "فَلَمْ يَكَدْ يَغِيبَ عَنْ عَيْنِي حَتَّى كَادَ قَلْبِي يَتَمَزَّقُ عَلَيْهِ، فَكَيْفَ إِذَا غَابَ عَنِّي لِشُهُورٍ وَسَنَوَاتٍ؟", "segs": null, "full_uz": "Ko'zimdan bir ozgina g'oyib bo'lganida ham yuragim parchalanay der edi — uzoq oylar va yillar davomida g'oyib bo'lsa, qanday bo'lardi?", "note": null},
  {"num": 136, "time": "00:09:27,340 --> 00:09:32,720", "arabic": "كَانَ اللَّهُ فِي عَوْنِكِ يَا أُمَّ أَحْمَدَ، وَلَكِنْ قُولِي لِي كَيْفَ سَتَبْقِينَ وَحْدَكِ فِي غِيَابِ أَحْمَدَ", "segs": null, "full_uz": "Alloh senga yordamchi bo'lsin, Umm Ahmad, lekin ayt, Ahmad yo'q paytida yolg'iz qanday qolasan?", "note": null},
  {"num": 138, "time": "00:09:32,720 --> 00:09:39,180", "arabic": "لَقَدْ تَدَبَّرَ أَحْمَدُ الْأَمْرَ يَا أُمَّ خَالِدٍ، فَقَدْ طَلَبَ مِنْ أَحَدِ أَقَارِبِنَا أَنْ تَأْتِيَ ابْنَتُهُ الْمُطَلَّقَةُ", "segs": null, "full_uz": "Ahmad ishni oldindan o'ylab qo'ygan, Umm Xolid — u qarindoshlarimizdan biridan uning ajrashgan qizi kelishini so'ragan.", "note": null},
  {"num": 140, "time": "00:09:39,179 --> 00:09:43,760", "arabic": "وَابْنُهَا الْيَافِعُ لِلْمَبِيتِ عِنْدِي", "segs": null, "full_uz": "Va uning voyaga yetayotgan o'g'li ham men bilan tunashi uchun.", "note": null},
  {"num": 141, "time": "00:09:43,760 --> 00:09:48,619", "arabic": "ثُمَّ لَا تَنْسَيْ يَا أُمَّ خَالِدٍ فَالْحَيُّ بِأَكْمَلِهِ مِنْ أَقَارِبِنَا فَلَا تَخَافِي", "segs": null, "full_uz": "Va yana, unutma, Umm Xolid, mahalla to'lig'icha bizning qarindoshlarimizdan iborat, shuning uchun qo'rqma.", "note": null},
  {"num": 143, "time": "00:10:01,000 --> 00:10:04,300", "arabic": "أَنْتَ؟ نَعَمْ أَنْتَ", "segs": null, "full_uz": "Sen? — Ha, sen.", "note": null},
  {"num": 144, "time": "00:10:04,300 --> 00:10:06,000", "arabic": "لَبَّيْكَ يَا شَيْخَنَا", "segs": null, "full_uz": "Labbay, shayximiz.", "note": null},
  {"num": 145, "time": "00:10:06,000 --> 00:10:07,700", "arabic": "قُلْتَ لِي مَا اسْمُكَ؟", "segs": null, "full_uz": "Ismingiz nima deganingiz?", "note": null},
  {"num": 146, "time": "00:10:07,700 --> 00:10:10,700", "arabic": "تِلْمِيذُكَ أَحْمَدُ بْنُ حَنْبَلٍ الشَّيْبَانِيُّ", "segs": null, "full_uz": "Shogirdingiz Ahmad ibn Hanbal ash-Shayboniy.", "note": null},
  {"num": 147, "time": "00:10:10,700 --> 00:10:13,700", "arabic": "عَلَى مَنْ قَرَأْتَ الْحَدِيثَ فِي بَغْدَادَ؟", "segs": null, "full_uz": "Bag'dodda kimdan hadis o'qidingiz?", "note": null},
  {"num": 148, "time": "00:10:13,700 --> 00:10:20,559", "arabic": "اِخْتَلَفْتُ إِلَى حَلَقَاتِ الْقَاضِي أَبِي يُوسُفَ صَاحِبِ أَبِي حَنِيفَةَ", "segs": null, "full_uz": "Qozi Abu Yusuf — Abu Hanifaning shogirdi — halqalariga qatnadim.", "note": null},
  {"num": 149, "time": "00:10:20,559 --> 00:10:24,860", "arabic": "ثُمَّ اخْتَصَصْتُ بِالشَّيْخِ هُشَيْمِ بْنِ بَشِيرٍ الْوَاسِطِيِّ رَحِمَهُ اللَّهُ", "segs": null, "full_uz": "So'ngra shayx Hushaym ibn Bashir al-Vositiyga — Alloh unga rahm qilsin — bag'ishlandim.", "note": null},
  {"num": 150, "time": "00:10:24,860 --> 00:10:26,860", "arabic": "اَلشَّيْخُ هُشَيْمٌ؟ نِعْمَ الرَّجُلُ", "segs": null, "full_uz": "Shayx Hushaymmi? Qanday ajoyib odam.", "note": null},
  {"num": 151, "time": "00:10:26,860 --> 00:10:30,159", "arabic": "لَعَلَّكَ تَعْلَمُ أَنَّهُ مِنْ هُنَا مِنْ وَاسِطٍ؟", "segs": null, "full_uz": "Shoyad bilarsiz, u shu yerdan, Vositdan.", "note": null},
  {"num": 152, "time": "00:10:30,159 --> 00:10:32,559", "arabic": "أَجَلْ أَعْلَمُ يَا شَيْخَنَا", "segs": null, "full_uz": "Ha, bilaman, shayximiz.", "note": null},
  {"num": 153, "time": "00:10:32,559 --> 00:10:37,000", "arabic": "كَأَنِّي رَأَيْتُ فِي وَجْهِكَ ضِيقًا حِينَ سَمِعْتَ مِنِّي ذَلِكَ الْمِزَاحَ", "segs": null, "full_uz": "Go'yo o'sha hazilimni eshitganingda yuzingda noqulaylikni ko'rdim.", "note": null},
  {"num": 154, "time": "00:10:37,000 --> 00:10:39,800", "arabic": "اُغْفِرْ لِي يَا شَيْخَنَا", "segs": null, "full_uz": "Meni kechiring, shayximiz.", "note": null},
  {"num": 155, "time": "00:10:39,800 --> 00:10:47,839", "arabic": "وَلَكِنْ كَرِهَ إِلَى نَفْسِي الْمِزَاحُ وَإِنِّي لَأَشَدُّ كَرْهًا لَهُ فِي حَضْرَةِ حَدِيثِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ", "segs": null, "full_uz": "Lekin hazil menga yoqmaydi, va Rasululloh hadisi huzurida uni yanada ko'proq yomon ko'raman.", "note": null},
  {"num": 158, "time": "00:10:47,839 --> 00:10:51,199", "arabic": "أَلَكَ حَاجَةٌ أَقْضِيهَا لَكَ يَا شَيْخَنَا؟", "segs": null, "full_uz": "Sizga bajarib beradigan biror ehtiyojingiz bormi, shayximiz?", "note": null},
  {"num": 159, "time": "00:10:51,199 --> 00:10:56,459", "arabic": "لَا شُكْرًا يَا بُنَيَّ، اِمْضِ عَلَى بَرَكَةِ اللَّهِ", "segs": null, "full_uz": "Yo'q, rahmat, o'g'lim, Allohning barakati bilan boraver.", "note": null},
  {"num": 161, "time": "00:10:56,459 --> 00:11:00,140", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 162, "time": "00:11:00,140 --> 00:11:02,779", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 163, "time": "00:11:02,779 --> 00:11:04,779", "arabic": "وَلَهْفَ قَلْبِي عَلَيْكَ يَا وَلَدِي", "segs": null, "full_uz": "Yuragim senga qanchalar orziqmoqda, o'g'lim.", "note": null},
  {"num": 164, "time": "00:11:04,779 --> 00:11:08,779", "arabic": "تُرَى أَيْنَ أَنْتَ يَا أَحْمَدُ الْآنَ", "segs": null, "full_uz": "Qiziq, hozir qayerdasan, Ahmad.", "note": null},
  {"num": 166, "time": "00:11:08,779 --> 00:11:12,779", "arabic": "أَيُّ أَرْضٍ تُقِلُّكَ وَأَيُّ سَمَاءٍ تُظِلُّكَ", "segs": null, "full_uz": "Qaysi yer seni ko'tarib yuribdi, qaysi osmon soya solmoqda.", "note": null},
  {"num": 168, "time": "00:11:12,779 --> 00:11:16,779", "arabic": "جَائِعٌ أَمْ أُطْعِمْتَ", "segs": null, "full_uz": "Ochmisan, ovqatlanganmisan.", "note": null},
  {"num": 170, "time": "00:11:16,779 --> 00:11:20,779", "arabic": "نَائِمٌ أَمْ جَافَاكَ النَّوْمُ", "segs": null, "full_uz": "Uxlayapsanmi, uyqu sendan yuz o'girganmi.", "note": null},
  {"num": 172, "time": "00:11:20,779 --> 00:11:23,779", "arabic": "لَهْفِي عَلَيْكَ يَا رُوحَ أُمِّكَ", "segs": null, "full_uz": "Onangning joni, senga qanchalar zorman.", "note": null},
  {"num": 173, "time": "00:11:31,000 --> 00:11:34,300", "arabic": "هَاتِي مَا عِنْدَكِ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Nima bilsang ayt, Abu al-Abbos.", "note": null},
  {"num": 174, "time": "00:11:34,300 --> 00:11:36,300", "arabic": "أَخْشَى يَا مَوْلَايَ", "segs": null, "full_uz": "Qo'rqaman, xo'jayinim.", "note": null},
  {"num": 175, "time": "00:11:36,300 --> 00:11:39,300", "arabic": "قُلْ مَا عِنْدَكَ صَرَاحَةً وَدُونَ مُوَارَبَةٍ، قُلْ", "segs": null, "full_uz": "Bilganingni ochiqchasiga, o'rab-chirmalmasdan ayt. Ayt.", "note": null},
  {"num": 177, "time": "00:11:39,300 --> 00:11:44,300", "arabic": "إِنَّ الْأَمْرَ حَوْلَ جَعْفَرٍ أَلَيْسَ كَذَلِكَ؟", "segs": null, "full_uz": "Ish Ja'far haqidamikan, shunday emasmi?", "note": null},
  {"num": 179, "time": "00:11:44,300 --> 00:11:46,300", "arabic": "كَيْفَ عَرَفْتَ يَا مَوْلَايَ؟", "segs": null, "full_uz": "Buni qayerdan bilding, xo'jayinim?", "note": null},
  {"num": 180, "time": "00:11:46,300 --> 00:11:51,300", "arabic": "فَلْتَغْفِرْ لِي فُضُولِي، لَا يَحْتَاجُ الْأَمْرُ إِلَى كَثِيرِ عَنَاءٍ لِمَنْ يَعْرِفُكَ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Qiziquvchanligimni kechirasiz — seni bilgan uchun bu ish katta mehnat talab qilmaydi, Abu al-Abbos.", "note": null},
  {"num": 182, "time": "00:11:51,300 --> 00:11:57,300", "arabic": "مَتَى أَرَدْتُ الْحَدِيثَ عَنْ جَعْفَرٍ الْبَرْمَكِيِّ بَدَأْتُ بِقَوْلِ أَخْشَى أَنْ... وَلَكِنْ... إِنَّمَا يَا مَوْلَايَ", "segs": null, "full_uz": "Ja'far al-Barmakiy haqida gapirmoqchi bo'lganimda, «qo'rqaman»... «lekin»... «faqat» deb boshlayman-a, xo'jayinim.", "note": null},
  {"num": 184, "time": "00:11:57,300 --> 00:12:02,140", "arabic": "حَدِيثُ مَوْلَايَ لَا يَنْقُصُهُ الطَّرَافَةُ وَلَا الذَّكَاءُ، وَلَكِنَّ الْأَمْرَ هَذِهِ الْمَرَّةَ شَدِيدُ الْخُطُورَةِ", "segs": null, "full_uz": "Xo'jayinimning gapida na o'tkirlik, na aql yetishmaydi, lekin bu safar ish juda xavflidir.", "note": null},
  {"num": 186, "time": "00:12:02,140 --> 00:12:06,140", "arabic": "وَأَخْشَى أَنَّهُ لَنْ يَسُرَّكَ أَبَدًا", "segs": null, "full_uz": "Va qo'rqamanki, bu sizni hech qachon xursand qilmaydi.", "note": null},
  {"num": 187, "time": "00:12:06,140 --> 00:12:10,140", "arabic": "وَمَا تُسَرِّنِي حَدِيثُكَ عَنْ جَعْفَرٍ يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Ja'far haqidagi gaping meni hech qachon xursand qilmaydi, Abu al-Abbos.", "note": null},
  {"num": 188, "time": "00:12:10,140 --> 00:12:14,700", "arabic": "قُلْ قُلْ مَا عِنْدَكَ قَبْلَ أَنْ يَقْتُلَكَ مَا يَغَصُّ بِهِ حَلْقُكَ", "segs": null, "full_uz": "Ayt, ayt, bilganingni, tomog'ingda tiqilib qolgan narsa seni o'ldirib qo'ymasin.", "note": "«يَغَصُّ بِهِ حَلْقُهُ» — «tomog'ida tiqilib qolgan», ya'ni aytishga qo'rqib turgan gap ma'nosidagi majoziy ibora."},
  {"num": 189, "time": "00:12:14,700 --> 00:12:16,700", "arabic": "اِجْلِسْ", "segs": null, "full_uz": "O'tir.", "note": null},
  {"num": 190, "time": "00:12:16,700 --> 00:12:22,700", "arabic": "جَعْفَرٌ الْبَرْمَكِيُّ أَطْلَقَ سَرَاحَ يَحْيَى بْنِ عَبْدِ اللَّهِ الطَّالِبِيِّ مِنْ سِجْنِي", "segs": null, "full_uz": "Ja'far al-Barmakiy Yahyo ibn Abdulloh at-Tolibiyni mening zindonimdan ozod qildi.", "note": null},
  {"num": 191, "time": "00:12:22,700 --> 00:12:25,700", "arabic": "وَمَا أَدْرَاكَ أَنِّي أَنَا مَنْ أَمَرَهُ بِذَلِكَ", "segs": null, "full_uz": "Qayerdan bilasan, bunga men buyurgan bo'lishim mumkinligini?", "note": null},
  {"num": 192, "time": "00:12:25,700 --> 00:12:31,000", "arabic": "لَا أَظُنُّ مَوْلَايَ أَمِيرَ الْمُؤْمِنِينَ يَأْمُرُ بِمِثْلِ هَذَا", "segs": null, "full_uz": "Xo'jayinim mo'minlar amiri bunga o'xshash narsaga buyurmaydi deb o'ylayman.", "note": null},
  {"num": 193, "time": "00:12:31,000 --> 00:12:35,000", "arabic": "وَقَدْ رَأَى مِنْ خِيَانَةِ هَذَا الطَّالِبِيِّ مَا يَمْنَعُهُ مِنْ ذَلِكَ", "segs": null, "full_uz": "Va bu Tolibiyning xiyonatidan shunday narsani ko'rganki, bu sizni undan qaytaradi.", "note": null},
  {"num": 194, "time": "00:12:35,000 --> 00:12:40,000", "arabic": "مَنْ يَعْرِفُ أَمِيرَ الْمُؤْمِنِينَ جَيِّدًا يَعْرِفُ مَدَى كُرْهِهِ لِأُولَئِكَ الْمَارِقِينَ الطَّالِبِيِّينَ", "segs": null, "full_uz": "Mo'minlar amirini yaxshi bilgan kishi, u Tolibiy mo'tadillarni qanchalik yomon ko'rishini biladi.", "note": null},
  {"num": 196, "time": "00:12:40,000 --> 00:12:45,300", "arabic": "وَمَنْ يَقِفُ مَعَهُمْ وَلَوْ كَانَ مِنْ أَقْرَبِ الْمُقَرَّبِينَ إِلَيْهِ", "segs": null, "full_uz": "Va ular tarafida turgan kishini ham, hatto eng yaqin odami bo'lsa ham.", "note": null},
  {"num": 197, "time": "00:12:45,300 --> 00:12:48,300", "arabic": "فَلْتَعْلَمْ يَا أَبَا الْعَبَّاسِ أَنَا لَا أَكْرَهُ الطَّالِبِيِّينَ", "segs": null, "full_uz": "Bilib qo'y, Abu al-Abbos, men Tolibiylarni yomon ko'rmayman.", "note": null},
  {"num": 198, "time": "00:12:48,300 --> 00:12:56,300", "arabic": "إِنَّمَا أَكْرَهُ سَعْيَهُمُ الدَّائِمَ لِلْوُصُولِ إِلَى مَآرِبِهِمْ صَارِفِينَ أَنْظَارَنَا وَأَنْظَارَهُمْ عَنْ خَطَرِ الرُّومِ الْمُحْدِقِ بِنَا", "segs": null, "full_uz": "Balki ularning o'z maqsadlariga yetish uchun doim harakat qilib, bizning va o'zlarining nazarini bizni o'rab olgan Rum xavfidan chalg'itishini yomon ko'raman.", "note": null},
  {"num": 199, "time": "00:12:56,300 --> 00:13:03,300", "arabic": "أَعْرِفُ ذَلِكَ يَا مَوْلَايَ وَأَعْرِفُ أَنَّ غُفْرَانَكَ لِأَمْثَالِ يَحْيَى بْنِ عَبْدِ اللَّهِ لَا يَزِيدُهُمْ إِلَّا تَمَادِيًا فِي الْخِلَافِ", "segs": null, "full_uz": "Buni bilaman, xo'jayinim, va bilamanki, Yahyo ibn Abdullohga o'xshaganlarni kechirishingiz ularni faqat ixtilofda davom ettirishga undaydi.", "note": null},
  {"num": 200, "time": "00:13:03,300 --> 00:13:10,300", "arabic": "وَلِذَا فَإِنَّ مَا فَعَلَهُ جَعْفَرٌ الْبَرْمَكِيُّ بَدَا لِي عَجَبًا لَا أَكَادُ أُصَدِّقُهُ", "segs": null, "full_uz": "Shuning uchun Ja'far al-Barmakiyning qilgan ishi menga ishonib bo'lmaydigan ajablanarli tuyuldi.", "note": null},
  {"num": 201, "time": "00:13:10,300 --> 00:13:13,300", "arabic": "وَهُوَ يَعْرِفُ مَوْقِفَكَ مِنْهُمْ", "segs": null, "full_uz": "Va u sizning ularga bo'lgan pozitsiyangizni biladi-ku.", "note": null},
  {"num": 202, "time": "00:13:13,300 --> 00:13:17,300", "arabic": "أَرْجُو أَنْ يَكُونَ مَا نَقَلْتَهُ إِلَيَّ صَحِيحًا يَا أَبَا الْعَبَّاسِ", "segs": null, "full_uz": "Umid qilamanki, menga yetkazganing to'g'ridir, Abu al-Abbos.", "note": null},
  {"num": 203, "time": "00:13:17,300 --> 00:13:22,300", "arabic": "وَإِلَّا فَوَاللَّهِ فَإِنَّكَ سَتُؤْنِسُ وَحْشَةَ يَحْيَى بْنِ عَبْدِ اللَّهِ فِي سِجْنِهِ", "segs": null, "full_uz": "Aks holda, vallohi, sen Yahyo ibn Abdullohning zindondagi yolg'izligiga hamroh bo'lasan.", "note": null},
  {"num": 204, "time": "00:13:22,300 --> 00:13:27,300", "arabic": "إِنْ يَكُنْ يَحْيَى بْنُ عَبْدِ اللَّهِ مَا زَالَ فِي سِجْنِهِ فَإِنَّنِي أَسْتَحِقُّ أَكْثَرَ مِنْ ذَلِكَ يَا مَوْلَايَ", "segs": null, "full_uz": "Agar Yahyo ibn Abdulloh hali zindonida bo'lsa, men bundan ham ko'proq jazoga loyiqman, xo'jayinim.", "note": null},
  {"num": 206, "time": "00:13:27,300 --> 00:13:30,300", "arabic": "سَنَرَى يَا أَبَا الْعَبَّاسِ سَنَرَى", "segs": null, "full_uz": "Ko'ramiz, Abu al-Abbos, ko'ramiz.", "note": null},
  {"num": 207, "time": "00:13:31,000 --> 00:13:35,000", "arabic": "أَمَّا الْحَدِيثُ السَّابِقُ فَقَدْ قَالَ يَحْيَى بْنُ سَعِيدٍ سَمِعْتُ سَالِمَ بْنَ عَبْدِ اللَّهِ يَقُولُ", "segs": null, "full_uz": "Oldingi hadisda esa Yahyo ibn Sa'id: «Solim ibn Abdullohdan eshitdim» deb aytgan.", "note": null},
  {"num": 209, "time": "00:13:35,000 --> 00:13:37,000", "arabic": "إِنْ أَذِنْتَ لِي يَا شَيْخَنَا", "segs": null, "full_uz": "Ruxsat bersangiz, shayximiz.", "note": null},
  {"num": 210, "time": "00:13:37,000 --> 00:13:38,700", "arabic": "مَاذَا تُرِيدُ؟", "segs": null, "full_uz": "Nima demoqchisan?", "note": null},
  {"num": 211, "time": "00:13:38,700 --> 00:13:44,300", "arabic": "لَيْسَ فِي الْحَدِيثِ السَّابِقِ «سَمِعْتُ» وَإِنَّمَا هِيَ «أَنَّ»، فَقَدْ قَالَ يَحْيَى بْنُ سَعِيدٍ أَنَّ سَالِمَ بْنَ عَبْدِ اللَّهِ يَقُولُ", "segs": null, "full_uz": "Oldingi hadisda «eshitdim» emas, balki «ki» so'zi bo'lishi kerak — Yahyo ibn Sa'id «Solim ibn Abdulloh aytadiki» deb aytgan.", "note": "Hadis rivoyat qilishda sanadning aniq so'zlari («سمعت», «عن», «أن» kabi) katta ahamiyatga ega — bu isnodning rivoyat turini bildiradi."},
  {"num": 213, "time": "00:13:44,300 --> 00:13:46,300", "arabic": "صَدَقْتَ", "segs": null, "full_uz": "To'g'ri aytding.", "note": null},
  {"num": 214, "time": "00:13:46,300 --> 00:13:49,300", "arabic": "اُكْتُبْ كَمَا قَالَ ابْنُ حَنْبَلٍ", "segs": null, "full_uz": "Ibn Hanbal aytganidek yoz.", "note": null},
  {"num": 215, "time": "00:13:56,300 --> 00:14:00,700", "arabic": "لَا أَدْرِي، هَذِهِ الْفَتَاةُ لَا تُفَارِقُ ذِهْنِي، مَا سِرُّ تَعَلُّقِي بِهَا؟", "segs": null, "full_uz": "Bilmayman, bu qiz xayolimdan chiqmayapti — unga bog'lanishimning siri nima?", "note": null},
  {"num": 216, "time": "00:14:00,700 --> 00:14:07,700", "arabic": "رُبَّمَا لِأَنَّنِي لَمَسْتُ فِي كَلَامِهَا صِدْقًا، أَوْ رُبَّمَا لِأَنَّهُ يَنْتَابُنِي شُعُورٌ قَوِيٌّ أَنَّهَا مَظْلُومَةٌ", "segs": null, "full_uz": "Balki uning gapida chinlikni his qilganim uchundir, yoki balki uning zulm ostida ekaniga kuchli his qilganim uchundir.", "note": null},
  {"num": 217, "time": "00:14:07,700 --> 00:14:13,700", "arabic": "لَوْ تُقْبِلُ بِهَا أُخْتِي لَاشْتَرَيْتُهَا مِنْ فَوْرِي، وَلَكِنَّهَا تَرْفُضُ كُلَّ الرَّفْضِ", "segs": null, "full_uz": "Agar singlim uni qabul qilsa, darhol sotib olardim, lekin u qat'iyan rad qiladi.", "note": null},
  {"num": 218, "time": "00:14:13,700 --> 00:14:19,700", "arabic": "أَنَا مَنْ يَتَحَمَّلُ جَرِيرَةَ رَفْضِ أُخْتِي لَهَا، ذَلِكَ أَنَّهُ مَا كَانَ عَلَيَّ أَنْ أُخْبِرَهَا بِمَا حَدَثَ مَعَهَا يَوْمَ أَنْ ذَهَبْتُ لِيَشْتَرِيَهَا", "segs": [{"ar": "أَنَا مَنْ يَتَحَمَّلُ جَرِيرَةَ رَفْضِ أُخْتِي لَهَا", "uz": "singlimning uni rad qilishining gunohini men ko'tarayapman"}, {"ar": "ذَلِكَ أَنَّهُ مَا كَانَ عَلَيَّ أَنْ أُخْبِرَهَا بِمَا حَدَثَ مَعَهَا يَوْمَ أَنْ ذَهَبْتُ لِيَشْتَرِيَهَا", "uz": "chunki uni sotib olgani borgan kunimdagi voqeani unga aytmasligim kerak edi"}], "full_uz": "Singlimning uni rad qilishining gunohini men ko'tarayapman — chunki uni sotib olgani borgan kunimdagi voqeani unga aytmasligim kerak edi.", "note": null},
  {"num": 220, "time": "00:14:19,700 --> 00:14:24,700", "arabic": "وَلَكِنَّنِي مَعَ ذَلِكَ سَأُحَاوِلُ إِقْنَاعَهَا مِنْ جَدِيدٍ", "segs": null, "full_uz": "Shunga qaramay, uni yana ishontirishga harakat qilaman.", "note": null},
  {"num": 221, "time": "00:14:31,000 --> 00:14:35,300", "arabic": "كَيْفَ حَالُكَ يَا أَبَا الْفَضْلِ؟", "segs": null, "full_uz": "Ahvolingiz qanday, Abu al-Fadl?", "note": null},
  {"num": 222, "time": "00:14:35,300 --> 00:14:37,300", "arabic": "اَلْحَمْدُ لِلَّهِ يَا مَوْلَايَ بِخَيْرٍ", "segs": null, "full_uz": "Alhamdulillah, yaxshi, xo'jayinim.", "note": null},
  {"num": 223, "time": "00:14:37,300 --> 00:14:39,300", "arabic": "مَا الْجَدِيدُ لَدَيْكَ؟", "segs": null, "full_uz": "Yangilik bormi?", "note": null},
  {"num": 224, "time": "00:14:39,300 --> 00:14:44,300", "arabic": "لَا جَدِيدَ فَوْقَ أَرْضِكَ يَا مَوْلَايَ، كُلُّ الْأُمُورِ كَمَا تُحِبُّ وَتَشْتَهِي", "segs": null, "full_uz": "Yeringizda hech qanday yangilik yo'q, xo'jayinim — hamma narsa sizning istaganingizdek.", "note": null},
  {"num": 226, "time": "00:14:44,300 --> 00:14:47,300", "arabic": "اَلْأُمُورُ بِخَيْرٍ وَالْحَمْدُ لِلَّهِ، اَلْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Ishlar yaxshi, Alhamdulillah, Alhamdulillah.", "note": null},
  {"num": 228, "time": "00:14:47,300 --> 00:14:51,300", "arabic": "قُلْ لِي مَا أَخْبَارُ الطَّالِبِيِّ فِي مَحْبِسِهِ؟ أَمَا زَالَ عَلَى مَا يَتَمَنَّى؟", "segs": null, "full_uz": "Ayt-chi, Tolibiyning zindondagi ahvoli qanday? Hali ham xohlagan holatidami?", "note": null},
  {"num": 230, "time": "00:14:51,300 --> 00:14:54,300", "arabic": "أَلَمْ تُرْهِقْهُ آمَالُهُ وَأَمَانِيُّهُ؟", "segs": null, "full_uz": "Umid va orzulari uni charchatmadimi?", "note": null},
  {"num": 231, "time": "00:14:54,300 --> 00:14:56,300", "arabic": "لَهُ أَنْ يَتَمَنَّى يَا مَوْلَايَ", "segs": null, "full_uz": "Orzu qilishga haqqi bor, xo'jayinim.", "note": null},
  {"num": 232, "time": "00:14:56,300 --> 00:14:58,300", "arabic": "وَكَيْفَ مَحْبِسُهُ عِنْدَكَ؟", "segs": null, "full_uz": "Sizdagi zindonida ahvoli qanday?", "note": null},
  {"num": 233, "time": "00:14:58,300 --> 00:15:00,300", "arabic": "كَالْعَادَةِ يَا مَوْلَايَ", "segs": null, "full_uz": "Odatdagidek, xo'jayinim.", "note": null},
  {"num": 234, "time": "00:15:00,300 --> 00:15:04,300", "arabic": "اَلْقَلِيلُ مِنَ الرَّاحَةِ وَالْكَثِيرُ مِنَ التَّنْكِيلِ", "segs": null, "full_uz": "Ozgina rohat, ko'proq jazo-qiynoq.", "note": null},
  {"num": 235, "time": "00:15:04,300 --> 00:15:07,300", "arabic": "أَسْتَحْلِفُكَ بِاللَّهِ أَهُوَ كَذَلِكَ؟", "segs": null, "full_uz": "Alloh haqi so'rayman, shundaymi?", "note": null},
  {"num": 237, "time": "00:15:07,300 --> 00:15:12,300", "arabic": "أَلَا، اَلْحَقِيقَةُ يَا مَوْلَايَ أَنَّهُ لَيْسَ كَذَلِكَ", "segs": null, "full_uz": "Yo'q, haqiqatda esa, xo'jayinim, unday emas.", "note": null},
  {"num": 240, "time": "00:15:12,300 --> 00:15:17,300", "arabic": "كَيْفَ؟ أَلَمْ تَقُلْ قَلِيلٌ مِنَ الرَّاحَةِ كَثِيرٌ مِنَ التَّجَاهُلِ؟", "segs": null, "full_uz": "Qanday qilib? Ozgina rohat, ko'p e'tiborsizlik demaganmiding?", "note": null},
  {"num": 241, "time": "00:15:17,300 --> 00:15:23,300", "arabic": "قَدْ رَأَيْتُ يَا مَوْلَايَ أَنَّ خَطَرَهُ قَدْ زَالَ عَنْ أَمِيرِ الْمُؤْمِنِينَ وَأَنَّ أَنْصَارَهُ قَدْ تَلَاشَوْا", "segs": null, "full_uz": "Ko'rdimki, xo'jayinim, uning mo'minlar amiriga xavfi yo'qolgan, va tarafdorlari tarqalib ketgan.", "note": null},
  {"num": 243, "time": "00:15:23,300 --> 00:15:26,300", "arabic": "فَأَطْلَقْتُهُ إِلَى حَيْثُ لَا نَرَاهُ وَلَا يَرَانَا", "segs": null, "full_uz": "Shuning uchun uni bizni ham, biz ham uni ko'rmaydigan joyga ozod qildim.", "note": null},
  {"num": 244, "time": "00:15:26,300 --> 00:15:30,300", "arabic": "أَحْسَنْتَ، أَحْسَنْتَ يَا أَبَا الْفَضْلِ", "segs": null, "full_uz": "Barakalla, barakalla, Abu al-Fadl.", "note": null},
  {"num": 246, "time": "00:15:30,300 --> 00:15:34,300", "arabic": "وَاللَّهِ كَأَنَّكَ تَقْرَأُ مَا فِي قَرَارَةِ نَفْسِي وَكَأَنِّي مُوعِزٌ إِلَيْكَ بِذَلِكَ", "segs": null, "full_uz": "Vallohi, go'yo qalbimning tubidagini o'qib olayapsan, go'yo men senga shu haqda ishora bergandekman.", "note": null},
  {"num": 248, "time": "00:15:34,300 --> 00:15:39,300", "arabic": "مَا بَيْنَنَا دَهْرٌ مِنَ الْأُلْفَةِ وَالْمَحَبَّةِ يَا مَوْلَايَ، أَيُّ مَرْءِ سُوءٍ أَنَا إِنْ لَمْ أَكُنْ لَكَ كَذَلِكَ", "segs": null, "full_uz": "Oramizda uzoq yillik ulfat va muhabbat bor, xo'jayinim — sizga shunday bo'lmasam, qanaqa yomon odam bo'lardim.", "note": null},
  {"num": 250, "time": "00:15:39,300 --> 00:15:41,300", "arabic": "أَتَأْذَنُ لِي يَا مَوْلَايَ", "segs": null, "full_uz": "Ruxsat berasizmi, xo'jayinim.", "note": null},
  {"num": 251, "time": "00:15:41,300 --> 00:15:45,300", "arabic": "صُحْبَتُكَ السَّلَامَةُ بِرِعَايَةِ اللَّهِ وَحِفْظِهِ", "segs": null, "full_uz": "Allohning himoyasi va saqlashi bilan omon-eson boring.", "note": null},
  {"num": 252, "time": "00:16:01,000 --> 00:16:05,300", "arabic": "اَلسَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ", "segs": null, "full_uz": "Sizga salom, Allohning rahmati va barakoti bo'lsin.", "note": null},
  {"num": 253, "time": "00:16:05,300 --> 00:16:07,300", "arabic": "وَعَلَيْكُمُ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Sizga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 254, "time": "00:16:07,300 --> 00:16:09,300", "arabic": "يَا ابْنَ أَحْمَدَ", "segs": null, "full_uz": "Ibn Ahmad!", "note": null},
  {"num": 255, "time": "00:16:09,300 --> 00:16:11,300", "arabic": "لَبَّيْكَ وَسَعْدَيْكَ يَا شَيْخَنَا", "segs": null, "full_uz": "Labbay va sa'dayk, shayximiz.", "note": null},
  {"num": 256, "time": "00:16:11,300 --> 00:16:16,300", "arabic": "تَعَالَ وَاجْلِسْ بِجَانِبِ شَيْخِكَ، قُلْتُ لَكَ تَعَالَ وَاجْلِسْ بِجَانِبِ شَيْخِكَ", "segs": null, "full_uz": "Kel, shayxingning yoniga o'tir. Senga kel, shayxingning yoniga o'tir dedim.", "note": null},
  {"num": 258, "time": "00:16:16,300 --> 00:16:20,300", "arabic": "مَكَانُكَ هُنَا مُنْذُ الْيَوْمِ يَا ابْنَ حَنْبَلٍ فَلَا تَبْرَحْ", "segs": null, "full_uz": "Bugundan o'rning shu yerda, Ibn Hanbal, joyingdan qo'zg'alma.", "note": null},
  {"num": 260, "time": "00:16:20,300 --> 00:16:22,300", "arabic": "بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ", "segs": null, "full_uz": "Bismillahir Rohmanir Rohim.", "note": null},
  {"num": 261, "time": "00:16:31,000 --> 00:16:36,300", "arabic": "أَسْتَغْرِبُ أَنَّكَ لَمْ تَخْرُجْ لِطَلَبِ الْعِلْمِ كَمَا فَعَلَ ابْنُ حَنْبَلٍ", "segs": null, "full_uz": "Ibn Hanbal qilganidek, ilm izlagani chiqmaganingdan hayronman.", "note": null},
  {"num": 262, "time": "00:16:36,300 --> 00:16:41,300", "arabic": "لَا أَكْتُمُكَ سِرًّا إِنَّ الْأَمْرَ بِرُمَّتِهِ بَدَأَ يُضْجِرُنِي، قَدْ سَئِمْتُ الطُّلَّابَ وَحَلَقَاتِ الْعِلْمِ", "segs": null, "full_uz": "Sirimni yashirmayman — bu ish butunlay meni zeriktirib qo'ydi, o'quvchilar va ilm halqalaridan charchadim.", "note": null},
  {"num": 264, "time": "00:16:41,300 --> 00:16:48,300", "arabic": "وَأُفَكِّرُ أَنْ أَطْلُبَ إِلَى عَمِّي هُبَيْرَةَ أَنْ يَجِدَ لِي عَمَلًا فِي دِيوَانِ الْقَصْرِ ثُمَّ أَبْحَثُ لِي عَنْ فَتَاةٍ أَتَزَوَّجُهَا وَأَرْتَاحُ", "segs": null, "full_uz": "Amakim Hubayradan saroy devonida menga ish topib berishni so'rashni, so'ngra uylanadigan qiz izlab tinchlanishni o'ylayapman.", "note": null},
  {"num": 266, "time": "00:16:48,300 --> 00:16:51,300", "arabic": "أَلَنْ تُتَابِعَ سَيْرَكَ فِي طَلَبِ الْعِلْمِ؟", "segs": null, "full_uz": "Ilm izlash yo'lingda davom etmaysanmi?", "note": null},
  {"num": 267, "time": "00:16:51,300 --> 00:16:55,300", "arabic": "إِنْ بَقِينَا نَرْكُضُ وَرَاءَ الْعِلْمِ فَسَنُنْفِقُ حَيَاتَنَا دُونَ مَا فَائِدَةٍ", "segs": null, "full_uz": "Agar ilm ortidan yugurishda davom etsak, hayotimizni foydasiz sarflab qo'yamiz.", "note": null},
  {"num": 268, "time": "00:16:55,300 --> 00:17:00,300", "arabic": "هَا أَنَا قَدْ تَقَلَّبْتُ بَيْنَ شُيُوخِ الْحَدِيثِ، أَلَا يَكْفِي ذَلِكَ؟ أَلَا يَكْفِي مَا تَعَلَّمْتُهُ؟", "segs": null, "full_uz": "Mana men hadis shayxlari orasida yurib chiqdim — bu yetmaydimi? O'rgangan narsam yetarli emasmi?", "note": null},
  {"num": 271, "time": "00:17:00,300 --> 00:17:04,300", "arabic": "اِبْنُ حَنْبَلٍ هَذَا يُرِيدُ أَنْ يُصْبِحَ كَمَالِكِ ابْنِ أَنَسٍ، لَنْ يَكُونَ ذَلِكَ", "segs": null, "full_uz": "Bu Ibn Hanbal Molik ibn Anasdek bo'lishni xohlaydi — bunday bo'lmaydi.", "note": null},
  {"num": 273, "time": "00:17:04,300 --> 00:17:09,300", "arabic": "زَمَنُ الْعُلَمَاءِ الْكِبَارِ انْتَهَى مَعَ أَبِي حَنِيفَةَ النُّعْمَانِ وَمَالِكِ ابْنِ أَنَسٍ رَحِمَهُمَا اللَّهُ", "segs": null, "full_uz": "Buyuk olimlar davri Abu Hanifa an-Nu'mon va Molik ibn Anas — Alloh ularga rahm qilsin — bilan tugadi.", "note": null},
  {"num": 274, "time": "00:17:09,300 --> 00:17:15,300", "arabic": "لَا لَا لَا أَنْتَ مُخْطِئٌ فِي هَذَا، أُمَّةُ النَّبِيِّ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَا يَنْقَطِعُ خَيْرُهَا أَبَدًا", "segs": null, "full_uz": "Yo'q, yo'q, yo'q, bunda xato qilyapsan — Payg'ambar Muhammad ummatining xayri hech qachon uzilmaydi.", "note": null},
  {"num": 276, "time": "00:17:15,300 --> 00:17:19,300", "arabic": "كُلَّ حِينٍ يَبْزُغُ فَجْرُ عَالِمٍ جَدِيدٍ", "segs": null, "full_uz": "Har vaqt yangi bir olimning tongi otadi.", "note": null},
  {"num": 277, "time": "00:17:19,300 --> 00:17:23,300", "arabic": "فِي الْأُولَى صَدَقْتَ، أَمَّا فِي الثَّانِيَةِ فَقُلْ لِي مِثْلَ مَنْ؟", "segs": null, "full_uz": "Birinchisida to'g'ri aytding, ikkinchisiga kelsak, kim kabi deysan?", "note": null},
  {"num": 279, "time": "00:17:23,300 --> 00:17:27,300", "arabic": "آهْ نَسِيتُ، شَيْخُكَ الْمَرِيسِيُّ", "segs": null, "full_uz": "Oh, esimdan chiqdi — shayxingiz Marisiy.", "note": null},
  {"num": 281, "time": "00:17:27,300 --> 00:17:30,300", "arabic": "إِنَّكَ سَفِيهٌ", "segs": null, "full_uz": "Sen ahmoq ekansan.", "note": null},
  {"num": 282, "time": "00:17:30,300 --> 00:17:34,300", "arabic": "اِهْدَأْ لَا تَغْضَبْ يَا غَدْرُ", "segs": null, "full_uz": "Tinchlan, jahling chiqmasin, do'stim.", "note": null},
  {"num": 283, "time": "00:17:34,300 --> 00:17:36,300", "arabic": "كُنْتُ أُمَازِحُكَ فَقَطْ", "segs": null, "full_uz": "Faqat hazillashayotgan edim.", "note": null},
  {"num": 284, "time": "00:17:41,000 --> 00:17:44,300", "arabic": "عَبْدَ اللَّهِ؟ عَبْدَ اللَّهِ؟ مَا ذَاكَ؟", "segs": null, "full_uz": "Abdulloh? Abdulloh? Nima gap bu?", "note": null},
  {"num": 285, "time": "00:17:44,300 --> 00:17:46,300", "arabic": "مُحَمَّدُ", "segs": null, "full_uz": "Muhammad!", "note": null},
  {"num": 286, "time": "00:17:46,300 --> 00:17:49,300", "arabic": "جُعِلْتُ فِدَاكَ يَا أَحْمَدُ", "segs": null, "full_uz": "Senga fido bo'lay, Ahmad, senga nima bo'ldi?", "note": null},
  {"num": 287, "time": "00:17:49,300 --> 00:17:52,300", "arabic": "لَا بَأْسَ عَلَيَّ، أَنَا بِخَيْرٍ وَالْحَمْدُ لِلَّهِ", "segs": null, "full_uz": "Menda hech gap yo'q, yaxshiman, Alhamdulillah.", "note": null},
  {"num": 288, "time": "00:17:52,300 --> 00:17:56,300", "arabic": "أَيُّ خَيْرٍ يَا صَدِيقِي؟ أَنْتَ بِالْكَادِ تُكَلِّمُنِي، قُلْ لِي بِمَا تَشْعُرُ", "segs": null, "full_uz": "Qanaqa yaxshi, do'stim? Sen gapirishga ham zo'rg'a majoling bor-ku, o'zingni qanday his qilyapsan, ayt.", "note": null},
  {"num": 289, "time": "00:17:56,300 --> 00:18:00,300", "arabic": "إِنَّهَا الْحُمَّى يَا مُحَمَّدُ، لَمْ تُفَارِقْنِي مُنْذُ الْأَمْسِ", "segs": null, "full_uz": "Bu — isitma, Muhammad, kechadan beri meni tark etmayapti.", "note": null},
  {"num": 290, "time": "00:18:00,300 --> 00:18:02,300", "arabic": "سَأَذْهَبُ لِأُحْضِرَ لَكَ الطَّبِيبَ", "segs": null, "full_uz": "Senga tabib chaqirib kelaman.", "note": null},
  {"num": 291, "time": "00:18:02,300 --> 00:18:06,300", "arabic": "لَا لَا لَا أَمْلِكُ أُجْرَةَ الطَّبِيبِ", "segs": null, "full_uz": "Yo'q, yo'q, tabib haqini to'lashga pulim yo'q.", "note": null},
  {"num": 292, "time": "00:18:06,300 --> 00:18:09,300", "arabic": "أَنَا أَمْلِكُ", "segs": null, "full_uz": "Menda bor.", "note": null},
  {"num": 293, "time": "00:18:09,300 --> 00:18:14,300", "arabic": "يَكْفِينِي مَاءُ زَمْزَمَ فَفِيهِ شِفَاءُ سَقَمٍ", "segs": null, "full_uz": "Menga zamzam suvi yetadi, unda kasallik shifosi bor.", "note": "Zamzam suvi hadisda «shifobaxsh, kasallikka davo» sifatida tilga olingan."},
  {"num": 295, "time": "00:18:14,300 --> 00:18:17,300", "arabic": "سَأُحْضِرُهُ لَكَ عَلَى الْفَوْرِ", "segs": null, "full_uz": "Darrov olib kelaman.", "note": null},
  {"num": 296, "time": "00:18:17,300 --> 00:18:19,300", "arabic": "بَارَكَ اللَّهُ فِيكَ", "segs": null, "full_uz": "Alloh senga baraka bersin.", "note": null},
  {"num": 297, "time": "00:18:31,000 --> 00:18:35,300", "arabic": "نَشَدْتُكَ اللَّهَ يَا أَمِيرَ الْمُؤْمِنِينَ أَلَا أَخْلَيْتَ لَنَا نَفْسَكَ هَذِهِ اللَّيْلَةَ", "segs": null, "full_uz": "Alloh haqi so'rayman, mo'minlar amiri, bu kechada o'zingizni bizga bag'ishlamaysizmi?", "note": null},
  {"num": 299, "time": "00:18:35,300 --> 00:18:38,300", "arabic": "إِنَّنَا مُشْتَاقُونَ لِلسَّهَرِ مَعَكَ بَعْدَ طُولِ غِيَابٍ", "segs": null, "full_uz": "Uzoq vaqt ko'rinmay yurganingizdan keyin siz bilan tunash sog'inchida qoldik.", "note": null},
  {"num": 300, "time": "00:18:38,300 --> 00:18:44,300", "arabic": "وَأَنَا وَاللَّهِ يَا أَبَا الْفَضْلِ مُشْتَاقٌ لِلسَّهَرِ وَالسَّمَرِ مَعَكُمْ", "segs": null, "full_uz": "Men ham, vallohi, Abu al-Fadl, sizlar bilan tunab, suhbatlashishga sog'ingandirman.", "note": null},
  {"num": 301, "time": "00:18:44,300 --> 00:18:50,300", "arabic": "وَلَكِنَّ أُمَّ مُحَمَّدٍ مُتَوَعِّكَةٌ قَلِيلًا وَيَجِبُ أَنْ أَذْهَبَ لِأَطْمَئِنَّ عَلَيْهَا", "segs": null, "full_uz": "Lekin Umm Muhammad biroz betob, va uning ahvolidan xabar olishga borishim kerak.", "note": null},
  {"num": 302, "time": "00:18:50,300 --> 00:18:52,300", "arabic": "أَبَا هَاشِمٍ", "segs": null, "full_uz": "Abu Hoshim.", "note": null},
  {"num": 303, "time": "00:18:52,300 --> 00:18:53,300", "arabic": "نَعَمْ", "segs": null, "full_uz": "Labbay.", "note": null},
  {"num": 304, "time": "00:18:53,300 --> 00:18:58,300", "arabic": "قُلْ لِمَوْلَاكَ إِنَّهُ يَبْخَلُ عَلَيْنَا بِنَفْسِهِ كَمَا لَمْ نَعْهَدْهُ مِنْ قَبْلُ", "segs": null, "full_uz": "Xo'jayiningizga ayting, ilgari ko'rmagan darajada o'zidan bizga baxillik qilyapti.", "note": null},
  {"num": 305, "time": "00:18:58,300 --> 00:19:01,300", "arabic": "أَعِدُكَ أَنَّكَ لَنْ تَبْقَى وَحِيدًا هَذِهِ اللَّيْلَةَ", "segs": null, "full_uz": "Senga va'da beraman, bu kecha yolg'iz qolmaysan.", "note": null},
  {"num": 306, "time": "00:19:01,300 --> 00:19:06,300", "arabic": "اِمْضِ إِلَى صَاحِبِكَ وَسُمَّارِكَ وَلَنْ تَشْعُرَ حَتَّى أَطْلُبَكَ", "segs": null, "full_uz": "Do'stlaring va suhbatdoshlaring huzuriga bor, seni chaqirtirmagunimcha sezmaysan ham.", "note": null},
  {"num": 307, "time": "00:19:06,300 --> 00:19:08,300", "arabic": "كَمَا تَشَاءُ يَا مَوْلَايَ", "segs": null, "full_uz": "Qanday xohlasangiz, xo'jayinim.", "note": null},
  {"num": 308, "time": "00:19:31,000 --> 00:19:34,300", "arabic": "مَسْرُورُ", "segs": null, "full_uz": "Masrur.", "note": null},
  {"num": 309, "time": "00:19:34,300 --> 00:19:35,300", "arabic": "مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
  {"num": 310, "time": "00:19:35,300 --> 00:19:39,300", "arabic": "اُدْعُ لِي ابْنَ الرَّبِيعِ وَمَنْ عِنْدَهُ مِنْ رُؤُوسِ الْجُنْدِ", "segs": null, "full_uz": "Ibn ar-Rabi'ni va u bilan bo'lgan qo'shin boshliqlarini chaqir.", "note": null},
  {"num": 312, "time": "00:19:39,300 --> 00:19:41,300", "arabic": "أَمْرُكَ مَوْلَايَ", "segs": null, "full_uz": "Amringiz bajo, xo'jayinim.", "note": null},
  {"num": 313, "time": "00:19:41,300 --> 00:19:46,300", "arabic": "لَا أُرِيدُ جَلَبَةً وَلَا ضَجِيجًا وَلَا تَأْذَنْ لِأَيِّ كَائِنٍ كَانَ", "segs": null, "full_uz": "Shovqin-suron bo'lmasin, va hech kimga ruxsat berma.", "note": null},
  {"num": 315, "time": "00:19:46,300 --> 00:19:48,300", "arabic": "بِالدُّخُولِ عَلَيْهِ", "segs": null, "full_uz": "Uning huzuriga kirishga.", "note": null},
  {"num": 316, "time": "00:19:48,300 --> 00:19:51,300", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ يَا مَوْلَايَ", "segs": null, "full_uz": "Eshitdim va bo'ysunaman, xo'jayinim.", "note": null},
  {"num": 317, "time": "00:19:51,300 --> 00:19:53,300", "arabic": "مَسْرُورُ", "segs": null, "full_uz": "Masrur.", "note": null},
  {"num": 318, "time": "00:19:53,300 --> 00:19:57,300", "arabic": "اَلْعَجَلَةَ الْعَجَلَةَ وَالْكِتْمَانَ الْكِتْمَانَ", "segs": null, "full_uz": "Tezroq, tezroq, va sirni sirligicha saqla.", "note": null},
  {"num": 320, "time": "00:19:57,300 --> 00:20:00,300", "arabic": "هَيَّا اِمْضِ", "segs": null, "full_uz": "Bo'l, bor.", "note": null},
  {"num": 325, "time": "00:20:31,000 --> 00:20:34,300", "arabic": "أَحْمَدُ اسْتَيْقَظْتَ؟", "segs": null, "full_uz": "Ahmad, uyg'ondingmi?", "note": null},
  {"num": 326, "time": "00:20:34,300 --> 00:20:37,300", "arabic": "فِي أَيِّ وَقْتٍ نَحْنُ الْآنَ يَا مُحَمَّدُ؟", "segs": null, "full_uz": "Hozir qaysi vaqtdamiz, Muhammad?", "note": null},
  {"num": 327, "time": "00:20:37,300 --> 00:20:40,300", "arabic": "اَلْحَمْدُ لِلَّهِ يَبْدُو أَنَّ الْحُمَّى قَدْ زَالَتْ", "segs": null, "full_uz": "Alhamdulillah, isitmang tushib qolganga o'xshaydi.", "note": null},
  {"num": 329, "time": "00:20:40,300 --> 00:20:45,300", "arabic": "لَا أَدْرِي وَلَكِنْ أَحْسَبُ أَنَّ اللَّيْلَةَ قَدْ قَارَبَتْ عَلَى الِانْتِصَافِ", "segs": null, "full_uz": "Bilmayman, lekin kecha yarmiga yaqinlashganga o'xshaydi.", "note": null},
  {"num": 330, "time": "00:20:45,300 --> 00:20:47,300", "arabic": "اَلْحَمْدُ لِلَّهِ عَلَى سَلَامَتِكَ", "segs": null, "full_uz": "Alhamdulillah, omon qolganingizga.", "note": null},
  {"num": 331, "time": "00:20:47,300 --> 00:20:51,300", "arabic": "سَلَّمَكَ اللَّهُ يَا مُحَمَّدُ وَجَزَاكَ اللَّهُ عَنِّي خَيْرًا", "segs": null, "full_uz": "Alloh seni asrasin, Muhammad, va senga mendan yaxshilik bersin.", "note": null},
  {"num": 332, "time": "00:20:51,300 --> 00:20:56,300", "arabic": "كَفَاكَ دَلَالًا يَا ابْنَ حَنْبَلٍ، مِنَ الْغَدِ سَوْفَ نَذْهَبُ إِلَى الدَّرْسِ سَوِيًّا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Bas endi noz-karashma, Ibn Hanbal, ertadan darsga birga boramiz, Alloh xohlasa.", "note": null},
  {"num": 334, "time": "00:21:01,000 --> 00:21:04,300", "arabic": "قَدْ رَأَيْتُ أُمِّي فِي مَنَامِي، رَأَيْتُهَا فِي حَالٍ لَا يَسُرُّنِي", "segs": null, "full_uz": "Onamni tushimda ko'rdim, uni meni xursand qilmaydigan holatda ko'rdim.", "note": null},
  {"num": 336, "time": "00:21:04,300 --> 00:21:08,300", "arabic": "وَحِيدَةً وَحَزِينَةً عَلَى فِرَاقِي", "segs": null, "full_uz": "Yolg'iz va mendan ayrilganidan g'amgin.", "note": null},
  {"num": 338, "time": "00:21:08,300 --> 00:21:13,300", "arabic": "أَهْوِنْ عَلَيْكَ يَا صَاحِبِي، إِنَّهَا أَضْغَاثُ أَحْلَامٍ مِنْ آثَارِ الْحُمَّى", "segs": null, "full_uz": "O'zingga yengil tut, do'stim, bu isitma qoldirgan parishon tushdir.", "note": null},
  {"num": 340, "time": "00:21:13,300 --> 00:21:19,300", "arabic": "لَا يَا ابْنَ الْمُلَحِّ، لَيْسَ الْأَمْرُ كَمَا تَقُولُ", "segs": null, "full_uz": "Yo'q, do'stim, ish sen aytganidek emas.", "note": null},
  {"num": 342, "time": "00:21:19,300 --> 00:21:25,300", "arabic": "مَا كَانَ يَجِبُ عَلَيْنَا تَرْكُ أُمِّي وَحْدَهَا، وَأَرَى أَنْ نَعُودَ إِلَى بَغْدَادَ بِأَسْرَعِ مَا يَكُونُ", "segs": null, "full_uz": "Onamni yolg'iz qoldirmasligimiz kerak edi, va menimcha, tezroq Bag'dodga qaytishimiz lozim.", "note": null},
  {"num": 344, "time": "00:21:25,300 --> 00:21:27,300", "arabic": "بِهَذِهِ السُّرْعَةِ؟ أَجَلْ بِهَذِهِ السُّرْعَةِ", "segs": null, "full_uz": "Bunday tezmi? — Ha, shunday tez.", "note": null},
  {"num": 346, "time": "00:21:27,300 --> 00:21:30,300", "arabic": "قَلَقِي عَلَى أُمِّي يَكَادُ يَقْتُلُنِي", "segs": null, "full_uz": "Onam haqidagi xavotirim meni deyarli o'ldirayozdi.", "note": null},
  {"num": 347, "time": "00:21:30,300 --> 00:21:35,300", "arabic": "كَمَا تَشَاءُ، وَلَكِنْ نَمْكُثْ هُنَا يَوْمَيْنِ أَوْ ثَلَاثَةً", "segs": null, "full_uz": "Qanday xohlasang, lekin bu yerda ikki-uch kun qolamiz.", "note": null},
  {"num": 348, "time": "00:21:35,300 --> 00:21:39,300", "arabic": "رَيْثَمَا تَتَعَافَى وَبَعْدَهَا نَعُودُ إِلَى بَغْدَادَ", "segs": null, "full_uz": "Sen tuzalguningcha, keyin Bag'dodga qaytamiz.", "note": null},
  {"num": 349, "time": "00:22:01,000 --> 00:22:07,300", "arabic": "فَلْيَعْلَمِ الْجَمِيعُ أَنَّ الْأَمْرَ قَدْ قُضِيَ وَأَصْبَحَ فِي عِدَادِ الْمَاضِي", "segs": null, "full_uz": "Hamma bilib qo'ysinki, ish hal bo'ldi va o'tmish qatoriga o'tdi.", "note": null},
  {"num": 351, "time": "00:22:07,300 --> 00:22:11,300", "arabic": "وَلَمْ يَبْقَ إِلَّا أَنْ يَرَاهُ هَارُونُ بِأُمِّ عَيْنِهِ", "segs": null, "full_uz": "Faqat Horunning bu ishni o'z ko'zi bilan ko'rishi qolgan xolos.", "note": null},
  {"num": 352, "time": "00:22:11,300 --> 00:22:16,300", "arabic": "لَا أُرِيدُ لِأَحَدٍ أَنْ يَشْعُرَ بِشَيْءٍ حَتَّى نَتَدَارَكَ أَيَّ تَمَرُّدٍ مُحْتَمَلٍ", "segs": null, "full_uz": "Ehtimoliy har qanday isyonning oldini olguncha, hech kim hech narsani sezishini istamayman.", "note": null},
  {"num": 353, "time": "00:22:16,300 --> 00:22:20,300", "arabic": "أُرِيدُ أَنْ يُصْبِحَ أَهْلُ بَغْدَادَ كَمَا أَمْسَوْا", "segs": null, "full_uz": "Bag'dod ahli kechqurun qanday bo'lgan bo'lsa, ertalab ham shunday bo'lishini istayman.", "note": null},
  {"num": 354, "time": "00:22:20,300 --> 00:22:24,300", "arabic": "لَا يَشْعُرُونَ بِمَا حَدَثَ إِلَّا وَقَدْ حَدَثَ", "segs": null, "full_uz": "Bo'lgan voqeani, u allaqachon sodir bo'lgandan keyingina his qilsinlar.", "note": null},
  {"num": 355, "time": "00:22:24,300 --> 00:22:28,300", "arabic": "وَأَيُّ خَطَإٍ مِنْ أَيِّ شَخْصٍ كَانَ", "segs": null, "full_uz": "Va kim tomonidan biror xato bo'ladigan bo'lsa.", "note": null},
  {"num": 356, "time": "00:22:28,300 --> 00:22:31,300", "arabic": "أَنْتُمْ جَمِيعًا مَنْ سَيَدْفَعُ ثَمَنَهُ", "segs": null, "full_uz": "Uning bahosini hammangiz to'laysiz.", "note": null},
  {"num": 357, "time": "00:22:31,300 --> 00:22:35,300", "arabic": "فَلْيَكُنْ مَوْلَايَ عَلَى ثِقَةٍ أَنَّ الْأَمْرَ أَمْسَى حَتْمًا مَقْضِيًّا إِنْ شَاءَ اللَّهُ", "segs": null, "full_uz": "Xo'jayinim ishonch hosil qilsinki, ish, Alloh xohlasa, muqarrar hal bo'ldi.", "note": null},
  {"num": 358, "time": "00:22:35,300 --> 00:22:37,300", "arabic": "اِمْضُوا بِحِفْظِ اللَّهِ وَتَوْفِيقِهِ", "segs": null, "full_uz": "Allohning himoyasi va muvaffaqiyati bilan boringlar.", "note": null},
  {"num": 359, "time": "00:22:37,300 --> 00:22:40,300", "arabic": "فَلْيَأْذَنْ لَنَا أَمِيرُ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiri bizga ruxsat bersin.", "note": null},
  {"num": 362, "time": "00:23:01,000 --> 00:23:04,300", "arabic": "أَمْرُكَ مَوْلَايَ", "segs": null, "full_uz": "Amringiz bajo, xo'jayinim.", "note": null},
  {"num": 363, "time": "00:23:04,300 --> 00:23:08,300", "arabic": "نَفَّذْتُ مَا أَمَرْتَنِي بِهِ يَا كَبِيرُ", "segs": null, "full_uz": "Buyurgan ishingizni bajardim, ustoz.", "note": null},
  {"num": 364, "time": "00:23:08,300 --> 00:23:11,300", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ", "segs": null, "full_uz": "Eshitdim va bo'ysunaman.", "note": null},
  {"num": 365, "time": "00:23:11,000 --> 00:23:14,300", "arabic": "مَاذَا يَجْرِي يَا أَبَا هَاشِمٍ؟", "segs": null, "full_uz": "Nima bo'layapti, Abu Hoshim?", "note": null},
  {"num": 366, "time": "00:23:14,300 --> 00:23:18,300", "arabic": "قُضِيَ الْأَمْرُ يَا أَبَا الْفَضْلِ، فَقَدْ أَصْدَرَ أَمِيرُ الْمُؤْمِنِينَ حُكْمَهُ فِيهِ", "segs": null, "full_uz": "Ish hal bo'ldi, Abu al-Fadl — mo'minlar amiri unga hukmini chiqardi.", "note": null},
  {"num": 368, "time": "00:23:18,300 --> 00:23:22,300", "arabic": "وَلَكِنْ، لَيْسَ هُنَاكَ مُتَّسَعٌ لِلْـ«لَكِنْ»", "segs": null, "full_uz": "Lekin... — «Lekin» uchun endi joy qolmadi.", "note": null},
  {"num": 371, "time": "00:23:31,000 --> 00:23:34,300", "arabic": "هَيَّا تَحَرَّكْ يَا ابْنَ بَرْمَكَ، لَقَدِ انْتَهَى أَمْرُكُمْ", "segs": null, "full_uz": "Bo'l, qimirla, Barmak o'g'li, ishingiz tugadi.", "note": null},
  {"num": 373, "time": "00:23:34,300 --> 00:23:36,300", "arabic": "هَيَّا", "segs": null, "full_uz": "Bo'l.", "note": null},
  {"num": 374, "time": "00:23:41,000 --> 00:23:43,300", "arabic": "هَيَّا تَحَرَّكْ", "segs": null, "full_uz": "Bo'l, qimirla.", "note": null},
  {"num": 375, "time": "00:23:43,300 --> 00:23:45,300", "arabic": "هَيَّا", "segs": null, "full_uz": "Bo'l.", "note": null},
  {"num": 377, "time": "00:23:45,300 --> 00:23:50,300", "arabic": "دَعُوا الْفَضْلَ وَيَحْيَى وَمُوسَى فِي السِّجْنِ", "segs": null, "full_uz": "Fadl, Yahyo va Musoni zindonda qoldiring.", "note": null},
  {"num": 378, "time": "00:23:53,000 --> 00:23:56,300", "arabic": "أَمَّا نِسَاؤُهُمْ وَأَطْفَالُهُمْ فَلَا شَأْنَ لَكُمْ بِهِمْ", "segs": null, "full_uz": "Ularning xotinlari va bolalariga esa sizning ishingiz yo'q.", "note": null},
  {"num": 380, "time": "00:23:56,300 --> 00:23:59,300", "arabic": "كَمَا يَأْمُرُ مَوْلَايَ أَمِيرُ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Xo'jayinim mo'minlar amiri buyurgandek.", "note": null},
  {"num": 381, "time": "00:23:59,300 --> 00:24:01,300", "arabic": "عِيسَى", "segs": null, "full_uz": "Iso.", "note": null},
  {"num": 382, "time": "00:24:01,300 --> 00:24:03,300", "arabic": "لَبَّيْكَ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Labbay, mo'minlar amiri.", "note": null},
  {"num": 383, "time": "00:24:06,000 --> 00:24:09,300", "arabic": "لَا تُضَيِّقُوا عَلَى يَحْيَى وَأَبْنَائِهِ فِي السِّجْنِ", "segs": null, "full_uz": "Zindonda Yahyo va uning o'g'illariga tazyiq qilmang.", "note": null},
  {"num": 384, "time": "00:24:09,300 --> 00:24:12,300", "arabic": "اَلسَّمْعُ وَالطَّاعَةُ يَا أَمِيرَ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Eshitdim va bo'ysunaman, mo'minlar amiri.", "note": null},
  {"num": 385, "time": "00:24:12,300 --> 00:24:14,300", "arabic": "اِمْضُوا إِلَى شُؤُونِكُمْ", "segs": null, "full_uz": "O'z ishlaringizga boring.", "note": null},
  {"num": 386, "time": "00:24:31,000 --> 00:24:34,300", "arabic": "اَلسَّلَامُ عَلَى أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Mo'minlar amiriga salom.", "note": null},
  {"num": 387, "time": "00:24:34,300 --> 00:24:36,300", "arabic": "عَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ", "segs": null, "full_uz": "Senga ham salom va Allohning rahmati bo'lsin.", "note": null},
  {"num": 388, "time": "00:24:36,300 --> 00:24:40,300", "arabic": "جَعْفَرٌ الْبَرْمَكِيُّ لَمْ يُعْثَرْ عَلَيْهِ فِي السِّجْنِ يَا مَوْلَايَ", "segs": null, "full_uz": "Ja'far al-Barmakiy zindonda topilmadi, xo'jayinim.", "note": null},
  {"num": 390, "time": "00:24:41,000 --> 00:24:44,300", "arabic": "أَيْضًا لَعَلَّهُمْ وَضَعُوهُ فِي سِجْنٍ آخَرَ", "segs": null, "full_uz": "Balki uni boshqa zindonga qamashgandir.", "note": null},
  {"num": 391, "time": "00:24:44,300 --> 00:24:48,300", "arabic": "أَتَعْتَقِدُونَ أَنَّ جَعْفَرًا فَرَّ قَبْلَ أَنْ يُدْرِكَهُ الْجُنْدُ؟", "segs": null, "full_uz": "Ja'far askarlar yetib kelishidan oldin qochdi deb o'ylaysizlarmi?", "note": null},
  {"num": 392, "time": "00:24:48,300 --> 00:24:51,300", "arabic": "لَيْسَ مِنْ شِيمَةِ جَعْفَرٍ الْهَرَبُ", "segs": null, "full_uz": "Qochish Ja'farning xulqidan emas.", "note": null},
  {"num": 393, "time": "00:24:51,300 --> 00:24:55,300", "arabic": "لَسْتُ مُرْتَاحًا لِعَدَمِ مَجِيئِهِمْ بِجَعْفَرٍ حَتَّى السَّاعَةِ", "segs": null, "full_uz": "Hozirgacha Ja'farni olib kelmayotganlaridan xotirjam emasman.", "note": null},
  {"num": 394, "time": "00:24:55,300 --> 00:24:58,300", "arabic": "لَعَلَّ صُحْبَتَهُ لِهَارُونَ قَدْ أَفَادَتْ", "segs": null, "full_uz": "Balki uning Horun bilan hamrohligi foyda bergandir.", "note": null},
  {"num": 395, "time": "00:24:58,300 --> 00:25:01,300", "arabic": "مَا ضَرَّهُ وَضَرَّنَا إِلَّا صُحْبَتُهُ لِهَارُونَ", "segs": null, "full_uz": "Unga ham, bizga ham zarar keltirgan narsa faqat uning Horun bilan hamrohligi bo'ldi.", "note": null},
  {"num": 402, "time": "00:25:31,000 --> 00:25:35,300", "arabic": "يَا اللَّهُ", "segs": null, "full_uz": "Yo Alloh.", "note": null},
  {"num": 403, "time": "00:25:35,300 --> 00:25:37,300", "arabic": "لَا أَكَادُ أُصَدِّقُ", "segs": null, "full_uz": "Ishonib bo'lmayapti.", "note": null},
  {"num": 404, "time": "00:25:37,300 --> 00:25:39,300", "arabic": "أَنَا هُنَا", "segs": null, "full_uz": "Men shu yerdaman.", "note": null},
  {"num": 407, "time": "00:25:39,300 --> 00:25:41,300", "arabic": "مَسْرُورُ", "segs": null, "full_uz": "Masrur.", "note": null},
  {"num": 408, "time": "00:25:41,300 --> 00:25:43,300", "arabic": "قُلْ لِي يَا مَسْرُورُ", "segs": null, "full_uz": "Ayt-chi, Masrur.", "note": null},
  {"num": 411, "time": "00:25:43,300 --> 00:25:46,300", "arabic": "إِنَّهَا أَوَامِرُ أَمِيرِ الْمُؤْمِنِينَ", "segs": null, "full_uz": "Bu — mo'minlar amirining amri.", "note": null},
  {"num": 412, "time": "00:25:46,300 --> 00:25:48,300", "arabic": "دَعْنِي أُكَلِّمْهُ", "segs": null, "full_uz": "Menga u bilan gaplashishga imkon ber.", "note": null},
  {"num": 414, "time": "00:25:48,300 --> 00:25:50,300", "arabic": "مَسْرُورُ", "segs": null, "full_uz": "Masrur.", "note": null},
  {"num": 415, "time": "00:25:50,300 --> 00:25:52,300", "arabic": "أَتَوَسَّلُ إِلَيْكَ؟", "segs": null, "full_uz": "Sendan yolvorib so'rasam bo'ladimi?", "note": null},
  {"num": 416, "time": "00:25:52,300 --> 00:25:55,300", "arabic": "أَخْشَى أَنَّهُ لَا سَبِيلَ لِذَلِكَ يَا أَبَا الْفَضْلِ", "segs": null, "full_uz": "Qo'rqamanki, bunga yo'l yo'q, Abu al-Fadl.", "note": null},
  {"num": 417, "time": "00:25:55,300 --> 00:25:57,300", "arabic": "أَرْجُوكَ، أَرْجُوكَ يَا أَبَا هَاشِمٍ", "segs": null, "full_uz": "Iltimos, iltimos, Abu Hoshim.", "note": null},
  {"num": 419, "time": "00:25:57,300 --> 00:25:59,300", "arabic": "أَتَوَسَّلُ إِلَيْكَ", "segs": null, "full_uz": "Sendan yolvorib so'rayman.", "note": null},
  {"num": 420, "time": "00:25:59,300 --> 00:26:01,300", "arabic": "حَسَنًا", "segs": null, "full_uz": "Xo'p.", "note": null},
  {"num": 422, "time": "00:26:11,000 --> 00:26:14,300", "arabic": "إِنَّهُ غَاضِبٌ بِلَا شَكٍّ، أَنَا أَعْرِفُ هَارُونَ عِنْدَمَا يَغْضَبُ", "segs": null, "full_uz": "U shubhasiz g'azablangan — men Horunni g'azablangan paytida bilaman.", "note": null},
  {"num": 424, "time": "00:26:14,300 --> 00:26:16,300", "arabic": "نَعَمْ", "segs": null, "full_uz": "Ha.", "note": null},
  {"num": 426, "time": "00:26:16,300 --> 00:26:19,300", "arabic": "هَارُونُ عِنْدَمَا يَسْتَبِدُّ بِهِ الْغَضَبُ", "segs": null, "full_uz": "Horunni g'azab qamrab olganida.", "note": null},
  {"num": 427, "time": "00:26:19,300 --> 00:26:21,300", "arabic": "اِسْتَعِيذُوا بِاللَّهِ مِنَ الشَّيْطَانِ", "segs": null, "full_uz": "Shaytondan Allohga sig'ininglar.", "note": null},
  {"num": 428, "time": "00:26:21,300 --> 00:26:23,300", "arabic": "لَا", "segs": null, "full_uz": "Yo'q.", "note": null},
  {"num": 429, "time": "00:26:23,300 --> 00:26:25,300", "arabic": "إِنَّهُ غَاضِبٌ", "segs": null, "full_uz": "U g'azablangan.", "note": null},
  {"num": 432, "time": "00:26:27,000 --> 00:26:31,300", "arabic": "سَيَعْرِفُ أَنَّ الْأَمْرَ لَا يَسْتَحِقُّ كُلَّ ذَلِكَ", "segs": null, "full_uz": "U bu ish bunchalikka arzimasligini bilib oladi.", "note": null},
  {"num": 433, "time": "00:26:31,300 --> 00:26:35,300", "arabic": "أَجَلْ أَجَلْ أَجَلْ", "segs": null, "full_uz": "Ha, ha, ha.", "note": null},
  {"num": 435, "time": "00:26:35,300 --> 00:26:39,300", "arabic": "سَيَطْلُبُ مَسْرُورٌ أَنْ أَرَاهُ وَسَيَنْدَمُ عَلَى كُلِّ شَيْءٍ فَعَلَهُ", "segs": null, "full_uz": "Masrur meni unga ko'rsatishni so'raydi, va u qilgan har bir ishiga pushaymon bo'ladi.", "note": null},
  {"num": 438, "time": "00:26:39,300 --> 00:26:42,300", "arabic": "إِنَّنِي أَعْرِفُ هَارُونَ، أَشُكُّ أَنَّهُ غَاضِبٌ", "segs": null, "full_uz": "Men Horunni bilaman, g'azablanganiga shubham bor.", "note": null},
  {"num": 442, "time": "00:26:42,300 --> 00:26:47,300", "arabic": "إِنَّهُ صَدِيقِي وَلَنْ يَفْعَلَ شَيْئًا", "segs": null, "full_uz": "U mening do'stim, hech narsa qilmaydi.", "note": null},
  {"num": 445, "time": "00:27:01,000 --> 00:27:03,300", "arabic": "أَيْنَ رَأْسُ جَعْفَرٍ يَا مَسْرُورُ", "segs": null, "full_uz": "Ja'farning boshi qayerda, Masrur?", "note": null},
  {"num": 446, "time": "00:27:03,300 --> 00:27:05,300", "arabic": "مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinim.", "note": null},
  {"num": 447, "time": "00:27:05,300 --> 00:27:09,300", "arabic": "لَقَدْ طَلَبَ مِنِّي أَنْ يَرَاكُمْ وَأَخْبَرَنِي مَا كَانَ بَيْنَكُمْ", "segs": null, "full_uz": "U sizni ko'rishni so'radi va oramizda nima bo'lganini menga aytdi.", "note": null},
  {"num": 449, "time": "00:27:09,300 --> 00:27:13,300", "arabic": "لَقَدْ تَوَسَّلَ إِلَيَّ مَوْلَايَ أَنْ تَرَاهُ وَبَعْدَهَا تَأْمُرُ بِمَا تَرَاهُ مُنَاسِبًا", "segs": null, "full_uz": "U sizni ko'rishni yolvorib so'radi, xo'jayinim, va shundan keyin munosib topgan buyrug'ingizni bering, dedi.", "note": null},
  {"num": 451, "time": "00:27:13,300 --> 00:27:16,300", "arabic": "وَأَنَا أَيْضًا أُرِيدُ رُؤْيَتَهُ أَيُّهَا الْأَحْمَقُ", "segs": null, "full_uz": "Men ham uni ko'rishni istayman, ey ahmoq.", "note": null},
  {"num": 452, "time": "00:27:16,300 --> 00:27:19,300", "arabic": "وَلَكِنِّي أُرِيدُ رُؤْيَتَهُ مَقْطُوعَ الرَّأْسِ", "segs": null, "full_uz": "Lekin uni boshi kesilgan holda ko'rishni istayman.", "note": null},
  {"num": 453, "time": "00:27:19,300 --> 00:27:24,300", "arabic": "اِذْهَبْ، اِذْهَبْ وَإِلَّا وَاللَّهِ صَارَ رَأْسُكَ رَأْسَهُ", "segs": null, "full_uz": "Bor, bor, aks holda, vallohi, boshing uning boshi bilan almashadi.", "note": null},
  {"num": 456, "time": "00:27:24,300 --> 00:27:26,300", "arabic": "هَيَّا", "segs": null, "full_uz": "Bo'l.", "note": null},
  {"num": 457, "time": "00:27:26,300 --> 00:27:28,300", "arabic": "أَمْرُ مَوْلَايَ", "segs": null, "full_uz": "Xo'jayinimning amri.", "note": null},
  {"num": 458, "time": "00:27:31,000 --> 00:27:34,300", "arabic": "إِخْوَانَنَا، صَارَ مُخْطِئًا", "segs": null, "full_uz": "Birodarlar, u xato qildi.", "note": null},
  {"num": 460, "time": "00:27:34,300 --> 00:27:37,300", "arabic": "هَارُونُ لَنْ يَسْمَحَ بِأَمْرٍ كَهَذَا", "segs": null, "full_uz": "Horun bunga o'xshash ishga yo'l qo'ymaydi.", "note": null},
  {"num": 462, "time": "00:27:37,300 --> 00:27:40,300", "arabic": "لَا شَكَّ أَنَّهُ غَاضِبٌ، أَجَلْ", "segs": null, "full_uz": "Shubhasiz u g'azablangan. — Ha.", "note": null},
  {"num": 464, "time": "00:27:40,300 --> 00:27:45,300", "arabic": "مَا فَعَلْتُهُ كَانَ خَطَأً لَا يُغْتَفَرُ، لَكِنَّ هَارُونَ لَنْ يَقِفَ عِنْدَ هَذَا الْحَدِّ", "segs": null, "full_uz": "Qilgan ishim kechirilmas xato edi, lekin Horun bu bilan to'xtab qolmaydi.", "note": null},
  {"num": 466, "time": "00:27:45,300 --> 00:27:47,300", "arabic": "إِنَّمَا بَيْنَنَا أَكْثَرُ مِنْ ذَلِكَ", "segs": null, "full_uz": "Oramizda bundan ko'proq narsa bor.", "note": null},
  {"num": 467, "time": "00:27:47,300 --> 00:27:52,300", "arabic": "غَدًا سَنَتَحَقَّقُ أَنَا وَهَارُونُ عِنْدَمَا نَتَذَكَّرُ مَا يَحْدُثُ الْآنَ", "segs": null, "full_uz": "Ertaga men va Horun hozir bo'layotgan narsani eslaganimizda, buni bilib olamiz.", "note": null},
  {"num": 470, "time": "00:27:52,300 --> 00:27:54,300", "arabic": "سَنَتْرُكُ", "segs": null, "full_uz": "Qoldiramiz.", "note": null},
  {"num": 472, "time": "00:27:54,300 --> 00:27:57,300", "arabic": "هَارُونُ صَاحِبِي وَلَنْ يَسْمَحَ بِقَتْلِي أَبَدًا", "segs": null, "full_uz": "Horun mening do'stim, meni o'ldirishga hech qachon yo'l qo'ymaydi.", "note": null},
  {"num": 474, "time": "00:27:57,300 --> 00:28:02,300", "arabic": "هَارُونُ لَا يُمْكِنُ أَنْ يَفْعَلَ ذَلِكَ، أَنَسِيَ هَؤُلَاءِ الْقَوْمُ أَنَّنِي جَعْفَرٌ الْبَرْمَكِيُّ", "segs": null, "full_uz": "Horun buni qila olmaydi — bu odamlar men Ja'far al-Barmakiy ekanimni unutishdimi?", "note": null},
  {"num": 476, "time": "00:28:02,300 --> 00:28:06,300", "arabic": "أَنَا جَعْفَرٌ الْبَرْمَكِيُّ أَيُّهَا الْأَغْبِيَاءُ، هَارُونُ لَنْ يُفَرِّطَ فِي جَعْفَرٍ، هَارُونُ لَنْ يَقْتُلَ جَعْفَرًا", "segs": null, "full_uz": "Men Ja'far al-Barmakiyman, ey ahmoqlar — Horun Ja'fardan voz kechmaydi, Horun Ja'farni o'ldirmaydi.", "note": null},
];

if (typeof module !== "undefined" && module.exports) {
  module.exports = lessons;
}